(function(A){Object.assign(A.D,{"G1106":{"l":"γνώμη","o":9,"ar":"<f><o>γνώμη</o>، <g>-ης, ἡ</g> </f> <s> <s n=\"1.\">في اليونانية الكلاسيكية: <b>وسيلة للمعرفة، علامة</b>. </s> <s n=\"2.\"><b>الذهن</b>، وعملياته ونتائجها؛ <s n=\"(a)\"><b>ذهن، فهم</b>؛ </s> <s n=\"(b)\"><b>قصد، نيّة</b>: <r v=\"Acts.20.3\"></r>؛ </s> <s n=\"(c)\"><b>حُكم، رأي</b>: <r v=\"1Cor.1.10\"></r>، <r v=\"Rev.17.13\"></r>؛ </s> <s n=\"(d)\"><b>مشورة، نصيحة</b>: <r v=\"1Cor.7.25\"></r>، <r v=\"1Cor.7.40\"></r> <r v=\"2Cor.8.10\"></r>، <r v=\"Phlm.1.14\"></r>؛ </s> <s n=\"(e)\"><b>قصد ملكي، أمر</b> (كما في دانيال وعزرا الأول والثاني): <r v=\"Rev.17.17\"></r>.</s> †</s> </s>","en":"<f><o>γνώμη</o>, <g>-ης, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γιγνώσκω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Bel.2.15\"></r> (<h n=\"H1881\">דָּת</h>), <r v=\"LXX:Ps.82.3\"></r> (<h n=\"H5475\">סוֹד</h>), elsewhere, chiefly II Es, for <h n=\"H2942\">טְעֵם</h> ;]</e> </et> <s> <s n=\"1.\"><b>a means of knowing, a token</b> (Theogn.). </s> <s n=\"2.\">In Attic writers, <b>the mind</b>, its operations and results (v. Edwards, <i>Lex.</i>, <i>App.</i>, A); <s n=\"(a)\"><b>mind, understanding</b>; </s> <s n=\"(b)\"><b>purpose, intention</b>: <r v=\"Acts.20.3\"></r>; </s> <s n=\"(c)\"><b>judgment, opinion</b>: <r v=\"1Cor.1.10\"></r>, <r v=\"Rev.17.13\"></r>; </s> <s n=\"(d)\"><b>counsel, advice</b>: <r v=\"1Cor.7.25\"></r>, <r v=\"1Cor.7.40\"></r> <r v=\"2Cor.8.10\"></r>, <r v=\"Phlm.1.14\"></r>; </s> <s n=\"(e)\"><b>royal purpose, decree</b> (as in Da, I and II Es): <r v=\"Rev.17.17\"></r> (Cremer, 671).</s> †</s> </s>"},"G1125":{"l":"γράφω","o":191,"ar":"<f><o>γράφω</o>، </f> <s> <s n=\"1.\">في اليونانية الكلاسيكية: <b>كشط، خدش</b>، ثم لاحقًا <b>رسم، خطّ</b>. </s> <s n=\"2.\"><b>كتب</b>؛ <s n=\"(a)\">عن تشكيل الحروف أو رسمها على مادة الكتابة: <r v=\"John.8.6\"></r>، <r v=\"Gal.6.11\"></r>، <r v=\"2Thess.3.17\"></r>؛ </s> <s n=\"(b)\">التعبير كتابةً، التدوين، التسجيل: <r v=\"Luke.1.63\"></r>، <r v=\"John.19.21\"></r>، <r v=\"John.19.22\"></r>، <r v=\"Rev.1.11\"></r>، <r v=\"Rev.1.19\"></r>، وفي مواضع أخرى؛ عن الكتاب المقدس بوصفه سلطة قائمة: <g>γέγραπται</g>: <i>مكتوب</i>: <r v=\"Matt.4.4\"></r>، <r v=\"Mark.7.6\"></r>، <r v=\"Luke.4.8\"></r>، <r v=\"Rom.1.17\"></r>، <r v=\"1Cor.1.31\"></r>، وفي مواضع أخرى؛ ونفسه يليه <g>ἐν</g>: <r v=\"Mark.1.2\"></r>، <r v=\"Acts.1.20\"></r>، وفي مواضع أخرى؛ مع المنصوب: <b>كتب عن</b>: <r v=\"John.1.46\"></r>، <r v=\"Rom.10.5\"></r>؛ يليه <g>περί</g>: <r v=\"Matt.26.24\"></r>، <r v=\"Mark.14.21\"></r>، <r v=\"John.5.46\"></r>، وفي مواضع أخرى؛ مع القابل: <r v=\"Luke.18.31\"></r>؛ ونفسه يليه <g>ἵνα</g>: <r v=\"Mark.12.19\"></r>، <r v=\"Luke.20.28\"></r>؛ <g>κατὰ τ. γεγραμμένον</g>: <r v=\"2Cor.4.13\"></r>؛ <g>γεγραμμένον ἐστί</g>: <r v=\"John.2.17\"></r>؛ <g>ἐγράφη</g>: <r v=\"Rom.4.24\"></r>؛ <g>ἐπ’ αὐτῷ γεγραμμένα</g>: <r v=\"John.12.16\"></r>؛ </s> <s n=\"(c)\">عن كتابة التوجيهات أو الأخبار، مع القابل للشخص: <r v=\"Rom.15.15\"></r>، <r v=\"2Cor.7.12\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(d)\">عمّا يحوي السجل أو الرسالة: <g>βιβλίον</g>: <r v=\"Mark.10.4\"></r>، <r v=\"John.21.25\"></r>، <r v=\"Rev.5.1\"></r>؛ <g>τίτλον</g>: <r v=\"John.19.19\"></r>؛ <g>ἐπιστολήν</g>: <r v=\"Acts.23.25\"></r>؛ <g>ἐντολήν</g>: <r v=\"Mark.10.5\"></r> (قارن <g>ἀπο-, ἐγ-, ἐπι-, κατα-, προ-</g>).</s> </s> </s>","en":"<f><o>γράφω</o>, [in LXX chiefly for <h n=\"H3789\">כּתב</h> ]; </f> <s> <s n=\"1.\"><b>to scrape, graze</b> (Hom.), and later (Hdt.) <b>to sketch, draw</b>. </s> <s n=\"2.\"><b>to write</b>; <s n=\"(a)\">of forming or tracing letters on writing material: <r v=\"John.8.6\"></r>, <r v=\"Gal.6.11\"></r>, <r v=\"2Thess.3.17\"></r>; </s> <s n=\"(b)\">to express in writing, commit to writing, record: <r v=\"Luke.1.63\"></r>, <r v=\"John.19.21\"></r>, <r v=\"John.19.22\"></r> <r v=\"Rev.1.11\"></r>, <r v=\"Rev.1.19\"></r> al.; of scripture as a standing authority (Deiss., <i>BS</i>, 112ff.), <g>γέγραπται</g>, <i>it stands written</i> (Luther), <r v=\"Matt.4.4\"></r>, <r v=\"Mark.7.6\"></r>, <r v=\"Luke.4.8\"></r>, <r v=\"Rom.1.17\"></r>, <r v=\"1Cor.1.31\"></r>, al.; id. seq. <g>ἐν</g>, <r v=\"Mark.1.2\"></r>, <r v=\"Acts.1.20\"></r>, al.; c. acc., <b>to write of</b>: <r v=\"John.1.46\"></r>, <r v=\"Rom.10.5\"></r>; seq. <g>περί</g>, <r v=\"Matt.26.24\"></r>, <r v=\"Mark.14.21\"></r>, <r v=\"John.5.46\"></r>; al.; c. dat. (WM, §31, 4), <r v=\"Luke.18.31\"></r>; id. seq. <g>ἵνα</g> (M, <i>Pr.</i>, 207f.), <r v=\"Mark.12.19\"></r>, <r v=\"Luke.20.28\"></r>; <g>κατὰ τ. γεγραμμένον</g>, <r v=\"2Cor.4.13\"></r>; <g>γεγραμμένον ἐστί</g>, <r v=\"John.2.17\"></r>; <g>ἐγράφη</g>, <r v=\"Rom.4.24\"></r>; <g>ἐπ’ αὐτῷ γεγραμμένα</g>, <r v=\"John.12.16\"></r>; </s> <s n=\"(c)\">of writing directions or information, c. dat. pers.: <r v=\"Rom.15.15\"></r>, <r v=\"2Cor.7.12\"></r>, al.; </s> <s n=\"(d)\">of that which contains the record or message: <g>βιβλίον</g>, <r v=\"Mark.10.4\"></r>, <r v=\"John.21.25\"></r>, <r v=\"Rev.5.1\"></r>; <g>τίτλον</g>, <r v=\"John.19.19\"></r>; <g>ἐπιστολήν</g>, <r v=\"Acts.23.25\"></r>; <g>ἐντολήν</g>, <r v=\"Mark.10.5\"></r> (cf. <g>ἀπο-, ἐγ-, ἐπι-, κατα-, προ-</g>).</s> </s> </s>"},"G1199":{"l":"δεσμός","o":3,"ar":"<f><o>δεσμός</o>، <g>-οῦ, ὁ</g></f> <s><b>رباط، قيد</b>: مجازيًا: <r v=\"Luke.13.16\"></r>؛ <g>ὁ δεσμὸς τ. γλώσσης</g>: <r v=\"Mark.7.35\"></r>. الجمع <g>δεσμοί</g>: <r v=\"Phil.1.13\"></r>؛ <g>δεσμά</g>: <r v=\"Luke.8.29\"></r>، <r v=\"Acts.16.26\"></r>، <r v=\"Acts.20.23\"></r>؛ المضاف إليه والقابل: <r v=\"Acts.23.29\"></r>، <r v=\"Acts.26.29\"></r>، <r v=\"Acts.26.31\"></r>، <r v=\"Phil.1.7\"></r>، <r v=\"Phil.1.14\"></r>، <r v=\"Phil.1.17\"></r>، <r v=\"Col.4.18\"></r>، <r v=\"2Tim.2.9\"></r>، <r v=\"Phlm.1.10\"></r>، <r v=\"Heb.11.36\"></r>، <r v=\"Jude.1.6\"></r>؛ <g>ἐν τοῖς δ. τοῦ εὐαγγελίου</g> <r v=\"Phlm.1.13\"></r>.†</s>","en":"<f><o>δεσμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>δέω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H631\">אסר</h> ;] </e> </et> <s><b>a band, bond</b>: metaph., <r v=\"Luke.13.16\"></r>; <g>ὁ δεσμὸς τ. γλώσσης</g>, <r v=\"Mark.7.35\"></r> (for this expression in <g>π.</g>, v. Deiss., <i>LAE</i>, 306 ff.; of actual bonds, v. Ruth., <i>Gr.</i>, 9). Pl., <g>δεσμοί</g>, <r v=\"Phil.1.13\"></r>; <g>δεσμά</g> (as also in cl.), <r v=\"Luke.8.29\"></r>, <r v=\"Acts.16.26\"></r> <r v=\"Acts.20.23\"></r>; gen., dat., <r v=\"Acts.23.29\"></r> <r v=\"Acts.26.29\"></r>, <r v=\"Acts.26.31\"></r>, <r v=\"Phil.1.7\"></r>, <r v=\"Phil.1.14\"></r>, <r v=\"Phil.1.17\"></r>, <r v=\"Col.4.18\"></r>, <r v=\"2Tim.2.9\"></r>, <r v=\"Phlm.1.10\"></r>, <r v=\"Heb.11.36\"></r>, <r v=\"Jude.1.6\"></r>; <g>ἐν τοῖς δ. τοῦ εὐαγγελίου</g> <r v=\"Phlm.1.13\"></r>.†</s>"},"G1198":{"l":"δέσμιος","o":16,"ar":"<f><o>δέσμιος</o>، <g>-ον</g> (وأيضًا <g>-α, -ον</g>)؛ </f> <s n=\"1.\"><b>رابط</b>. </s> <s n=\"2.\"><b>مقيَّد، أسير</b>؛ <g>ὁ δ.</g> اسمًا: <b>سجين، أسير</b>: <r v=\"Matt.27.15\"></r>، <r v=\"Matt.27.16\"></r>، <r v=\"Mark.15.6\"></r>، <r v=\"Acts.16.25\"></r>، <r v=\"Acts.16.27\"></r>، <r v=\"Acts.23.18\"></r>، <r v=\"Acts.25.14\"></r>، <r v=\"Acts.25.27\"></r>، <r v=\"Acts.28.16\"></r>، <r v=\"Acts.28.17\"></r>، <r v=\"Heb.10.34\"></r>، <r v=\"Heb.13.3\"></r>؛ <g>ὁ δ. τοῦ Χριστοῦ</g>: <r v=\"Eph.3.1\"></r>، <r v=\"2Tim.1.8\"></r>، <r v=\"Phlm.1.1\"></r>، <r v=\"Phlm.1.9\"></r>؛ <g>ὁ δ. ἐν κυρίῳ</g>: <r v=\"Eph.4.1\"></r>.†</s>","en":"<f><o>δέσμιος</o>, <g>-ον</g> (also <g>-α, -ον</g>; </f> <et> <e t=\"derivation\">&lt; <g>δεσμός</g>), [in LXX for <h n=\"H631\">אסר</h>;]</e> </et> <s n=\"1.\"><b>binding</b>. </s> <s n=\"2.\"><b>bound, captive</b>; <g>ὁ δ.</g>, as subst., <b>a prisoner</b>: <r v=\"Matt.27.15\"></r>, <r v=\"Matt.27.16\"></r>, <r v=\"Mark.15.6\"></r>, <r v=\"Acts.16.25\"></r>, <r v=\"Acts.16.27\"></r> <r v=\"Acts.23.18\"></r> <r v=\"Acts.25.14\"></r>, <r v=\"Acts.25.27\"></r> <r v=\"Acts.28.16\"></r> (Rec.) <r v=\"Acts.28.17\"></r>, <r v=\"Heb.10.34\"></r> <r v=\"Heb.13.3\"></r>; <g>ὁ δ. τοῦ Χριστοῦ</g>, <r v=\"Eph.3.1\"></r>, <r v=\"2Tim.1.8\"></r>, <r v=\"Phlm.1.1\"></r>, <r v=\"Phlm.1.9\"></r>; <g>ὁ δ. ἐν κυρίῳ</g>, <r v=\"Eph.4.1\"></r>.†</s>"},"G1163":{"l":"δεῖ","o":11,"ar":"<f><o>δεῖ </o> غير شخصي (<g>δέω</g>)، </f> <s><b>ينبغي، يجب، لا بد</b>: مع المصدر، <r v=\"Matt.26.54\"></r>، <r v=\"Mark.13.7\"></r>، <r v=\"Acts.5.29\"></r>، وفي مواضع أخرى؛ مع المنصوب والمصدر، <r v=\"Matt.16.21\"></r>، <r v=\"Mark.8.31\"></r>، <r v=\"John.3.7\"></r>، <r v=\"Acts.25.10\"></r>، وفي مواضع أخرى؛ مع حذف المنصوب، <r v=\"Matt.23.23\"></r>؛ ومع حذف المنصوب والمصدر، <r v=\"Mark.13.14\"></r>، <r v=\"Rom.1.27\"></r> <r v=\"Rom.8.26\"></r>؛ <g>οὐ (μὴ) δεῖ</g> (<l>non licet</l>)، <b>لا ينبغي، لا يجوز</b>: <r v=\"Acts.25.24\"></r>، <r v=\"2Tim.2.24\"></r>؛ الماضي الناقص، <g>ἔδει</g>، عن الضرورة أو الالتزام في الزمن الماضي بشأن حدث ماضٍ، <r v=\"Matt.18.33\"></r>، <r v=\"Luke.15.32\"></r>، <r v=\"John.4.4\"></r>، <r v=\"Acts.27.21\"></r>، وفي مواضع أخرى؛ بصيغة مركّبة، <g>δέον ἐστίν</g>، <r v=\"Acts.19.36\"></r>؛ وكذلك مع حذف <g>ἐστίν</g>، <r v=\"1Pet.1.6\"></r> <g>τὰ μὴ δέοντα</g> (= <g>ἃ οὐ δεῖ</g>) <r v=\"1Tim.5.13\"></r>.</s>","en":"<f><o>δεῖ </o> impersonal (<g>δέω</g>), </f> <et> <e t=\"septuagint\">[in LXX chiefly for infin. with <h n=\"H3926\">לְ</h> ;] </e> </et> <s><b>one must, it is necessary</b>: c. inf., <r v=\"Matt.26.54\"></r>, <r v=\"Mark.13.7\"></r>, <r v=\"Acts.5.29\"></r>, al.; c. acc. et inf., <r v=\"Matt.16.21\"></r>, <r v=\"Mark.8.31\"></r>, <r v=\"John.3.7\"></r>, <r v=\"Acts.25.10\"></r>, al.; with ellipse of acc., <r v=\"Matt.23.23\"></r>; of acc., and inf., <r v=\"Mark.13.14\"></r>, <r v=\"Rom.1.27\"></r> <r v=\"Rom.8.26\"></r>; <g>οὐ (μὴ) δεῖ</g> (<l>non licet</l>), <b>ought not, must not</b>: <r v=\"Acts.25.24\"></r>, <r v=\"2Tim.2.24\"></r>; impf., <g>ἔδει</g>, of necessity or obligation in past time regarding a past event (Bl., § 63, 4), <r v=\"Matt.18.33\"></r>, <r v=\"Luke.15.32\"></r>, <r v=\"John.4.4\"></r>, <r v=\"Acts.27.21\"></r>, al.; periphr., <g>δέον ἐστίν</g> (as in Attic, <g>χρεών ἐστι</g> = <g>χρή</g>, v.s. <g>δέον</g>), <r v=\"Acts.19.36\"></r>; id., with ellipse of <g>ἐστίν</g>, <r v=\"1Pet.1.6\"></r> <g>τὰ μὴ δέοντα</g> (= <g>ἃ οὐ δεῖ</g> <r v=\"1Tim.5.13\"></r>.</s> <sy><i>SYN.</i>: <g>ὀφείλει</g>, expressing moral obligation, as distinct from <g>δεῖ</g>, denoting logical necessity and <g>χρή</g>, a need which results from the fitness of things (v. Tr., <i>Syn.</i>, § cvii, 10; Westc. on <r v=\"Heb.2.1\"></r>, <r v=\"1John.2.6\"></r>; Hort on <r v=\"Jas.3.10\"></r>).</sy>"},"G1107":{"l":"γνωρίζω","o":25,"ar":"<f><o>γνωρίζω</o> </f> <s> <s n=\"1.\"><b>يتعرّف على، يكتشف، يعرف</b>: <r v=\"Phil.1.22\"></r>. </s> <s n=\"2.\"><b>يُعرِّف (يُعلِم)</b>: مع المنصوب، <r v=\"Rom.9.22\"></r>، <r v=\"Rom.9.23\"></r>؛ مع منصوب الشيء وقابل الشخص، <r v=\"Luke.2.15\"></r>، <r v=\"John.15.15\"></r> <r v=\"John.17.26\"></r>، <r v=\"Acts.2.28\"></r> <i>(السبعينية)</i>، <r v=\"1Cor.15.1\"></r>، <r v=\"2Cor.8.1\"></r>، <r v=\"Gal.1.11\"></r>، <r v=\"Eph.1.9\"></r> <r v=\"Eph.6.19\"></r>، <r v=\"Eph.6.21\"></r> <r v=\"Col.4.7\"></r>، <r v=\"Col.4.9\"></r> <r v=\"2Pet.1.16\"></r>؛ مع القابل، يليه <g>ὅτι</g>، <r v=\"1Cor.12.3\"></r>؛ يليه <g>τί</g>، <r v=\"Col.1.27\"></r>؛ <g>περί</g>، <r v=\"Luke.2.17\"></r>. المبني للمجهول، <r v=\"Acts.7.13\"></r>، <r v=\"Rom.16.26\"></r>، <r v=\"Eph.3.3\"></r>، <r v=\"Eph.3.6\"></r>، <r v=\"Eph.3.10\"></r>، <r v=\"Phil.4.6\"></r>.†</s> </s>","en":"<f><o>γνωρίζω</o> </f> <et> <e t=\"derivation\">(&lt; <g>γιγνώσκω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3045\">ידע</h> hi. ;]</e> </et> <s> <s n=\"1.\">as most commonly in cl., <b>to come to know, discover, know</b>: <r v=\"Phil.1.22\"></r> (but cf. R, mg.). </s> <s n=\"2.\"><b>to make known</b>: c. acc., <r v=\"Rom.9.22\"></r>, <r v=\"Rom.9.23\"></r>; c. acc. rei da.t. pers., <r v=\"Luke.2.15\"></r>, <r v=\"John.15.15\"></r> <r v=\"John.17.26\"></r>, <r v=\"Acts.2.28\"></r> <i>(LXX)</i>, <r v=\"1Cor.15.1\"></r>, <r v=\"2Cor.8.1\"></r>, <r v=\"Gal.1.11\"></r>, <r v=\"Eph.1.9\"></r> <r v=\"Eph.6.19\"></r>, <r v=\"Eph.6.21\"></r> <r v=\"Col.4.7\"></r>, <r v=\"Col.4.9\"></r> <r v=\"2Pet.1.16\"></r>; c. dat., seq. <g>ὅτι</g>, <r v=\"1Cor.12.3\"></r>; seq. <g>τί</g>, <r v=\"Col.1.27\"></r>; <g>περί</g>, <r v=\"Luke.2.17\"></r>. Pass., <r v=\"Acts.7.13\"></r>, <r v=\"Rom.16.26\"></r>, <r v=\"Eph.3.3\"></r>, <r v=\"Eph.3.6\"></r>, <r v=\"Eph.3.10\"></r>, <r v=\"Phil.4.6\"></r> (Cremer, 677; cf. <g>ἀνα-, δια-γνωρίζω</g>).†</s> </s>"},"G1118":{"l":"γονεύς","o":20,"ar":"<f><o>γονεύς</o>، <g>-έως, ὁ</g> </f> <s><b>والد، أب</b>؛ وغالبًا بالجمع، <g>οἱ γ.</g>، <i>الوالدان</i>: <r v=\"Luke.2.41\"></r>، <r v=\"Luke.2.43\"></r> <r v=\"Luke.8.56\"></r> <r v=\"Luke.21.16\"></r>، <r v=\"John.9.2\"></r>، <r v=\"John.9.3\"></r>، <r v=\"John.9.20\"></r>، <r v=\"John.9.22\"></r>، <r v=\"John.9.23\"></r> <r v=\"Rom.1.30\"></r>، <r v=\"2Cor.12.14\"></r>، <r v=\"Eph.6.1\"></r>، <r v=\"Col.3.20\"></r>، <r v=\"2Tim.3.2\"></r>؛ حالة النصب جمعًا، <g>γονεῖς</g>، <r v=\"Matt.10.21\"></r>، <r v=\"Mark.13.22\"></r>، <r v=\"Luke.2.27\"></r> <r v=\"Luke.18.29\"></r>، <r v=\"John.9.18\"></r>.†</s>","en":"<f><o>γονεύς</o>, <g>-έως, ὁ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γίγνομαι</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H1\">אָב</h>, <h n=\"H517\">אֵם</h> ;]</e> </et> <s><b>a begetter, a father</b>; mostly in pl., <g>οἱ γ.</g>, <i>parents</i>: <r v=\"Luke.2.41\"></r>, <r v=\"Luke.2.43\"></r> <r v=\"Luke.8.56\"></r> <r v=\"Luke.21.16\"></r>, <r v=\"John.9.2\"></r>, <r v=\"John.9.3\"></r>, <r v=\"John.9.20\"></r>, <r v=\"John.9.22\"></r>, <r v=\"John.9.23\"></r> <r v=\"Rom.1.30\"></r>, <r v=\"2Cor.12.14\"></r>, <r v=\"Eph.6.1\"></r>, <r v=\"Col.3.20\"></r>, <r v=\"2Tim.3.2\"></r>; acc. pl. (Hellenistic, v. Thackeray, <i>Gr.</i>, i, 148), <g>γονεῖς</g>, <r v=\"Matt.10.21\"></r>, <r v=\"Mark.13.22\"></r>, <r v=\"Luke.2.27\"></r> <r v=\"Luke.18.29\"></r>, <r v=\"John.9.18\"></r>.†</s>"},"G1108":{"l":"γνῶσις","o":29,"ar":"<f><o>γνῶσις</o>، <g>-εως, ἡ</g> </f> <s> <s n=\"1.\"><b>سعي إلى المعرفة، استقصاء، تحقيق</b>. </s> <s n=\"2.\"><b>معرفة (علم)</b>، وفي العهد الجديد خاصةً عن معرفة الحق الروحي: مطلقًا، <r v=\"Luke.11.52\"></r>، <r v=\"Rom.2.20\"></r> <r v=\"Rom.15.14\"></r>، <r v=\"1Cor.1.5\"></r> <r v=\"1Cor.8.1\"></r>، <r v=\"1Cor.8.7\"></r>، <r v=\"1Cor.8.10\"></r>، <r v=\"1Cor.8.11\"></r>، <r v=\"1Cor.13.2\"></r>، <r v=\"1Cor.13.8\"></r> <r v=\"1Cor.14.6\"></r>، <r v=\"2Cor.6.6\"></r> <r v=\"2Cor.8.7\"></r> <r v=\"2Cor.11.6\"></r>، <r v=\"Eph.3.19\"></r>، <r v=\"Col.2.3\"></r>، <r v=\"1Pet.3.7\"></r>، <r v=\"2Pet.1.5\"></r>، <r v=\"2Pet.1.6\"></r>؛ مع المضاف إليه المفعولي، <g>σωτηρίας</g>، <r v=\"Luke.1.77\"></r>؛ <g>τ. δόξης τ. θεοῦ</g>، <r v=\"2Cor.4.6\"></r>؛ <g>τ. θεοῦ</g>، <r v=\"2Cor.2.14\"></r> <r v=\"2Cor.10.5\"></r>؛ <g>Χριστοῦ Ἰησοῦ</g>، <r v=\"Phil.3.8\"></r>، <r v=\"2Pet.3.18\"></r>؛ مع المضاف إليه الفاعلي، <g>θεοῦ</g>، <r v=\"Rom.11.33\"></r>؛ <g>λόγος γνώσεως</g>، <r v=\"1Cor.12.8\"></r>؛ <g>ψευδωνύμου γνώσεως</g>، <r v=\"1Tim.6.20\"></r>.†</s></s>","en":"<f><o>γνῶσις</o>, <g>-εως, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γιγνώσκω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1847\">דַּעַת</h> ;]</e> </et> <s> <s n=\"1.\"><b>a seeking to know, inquiry, investigation</b>. </s> <s n=\"2.\"><b>knowledge</b>, in NT, specially of the kn. of spiritual truth: absol., <r v=\"Luke.11.52\"></r>, <r v=\"Rom.2.20\"></r> <r v=\"Rom.15.14\"></r>, <r v=\"1Cor.1.5\"></r> (Lft., <i>Notes</i>, 147) <r v=\"1Cor.8.1\"></r>, <r v=\"1Cor.8.7\"></r>, <r v=\"1Cor.8.10\"></r>, <r v=\"1Cor.8.11\"></r>, <r v=\"1Cor.13.2\"></r>, <r v=\"1Cor.13.8\"></r> <r v=\"1Cor.14.6\"></r>, <r v=\"2Cor.6.6\"></r> <r v=\"2Cor.8.7\"></r> <r v=\"2Cor.11.6\"></r>, <r v=\"Eph.3.19\"></r>, <r v=\"Col.2.3\"></r>, <r v=\"1Pet.3.7\"></r>, <r v=\"2Pet.1.5\"></r>, <r v=\"2Pet.1.6\"></r>; c. gen. obj., <g>σωτηρίας</g>, <r v=\"Luke.1.77\"></r>; <g>τ. δόξης τ. θεοῦ</g>, <r v=\"2Cor.4.6\"></r>; <g>τ. θεοῦ</g>, <r v=\"2Cor.2.14\"></r> <r v=\"2Cor.10.5\"></r>; <g>Χριστοῦ Ἰησοῦ</g>, <r v=\"Phil.3.8\"></r> (v. Deiss., <i>LAE</i>, 383<i>8</i>), <r v=\"2Pet.3.18\"></r>; c. gen. subjc., <g>θεοῦ</g>, <r v=\"Rom.11.33\"></r>; <g>λόγος γνώσεως</g>, <r v=\"1Cor.12.8\"></r>; <g>ψευδωνύμου γνώσεως</g>, <r v=\"1Tim.6.20\"></r>.†</s></s> <sy><i>SYN.</i>: <g>σοφία, φρόνησις</g> (cf. <g>ἐπί-γνωσις</g> and v. Lft. on <r v=\"Col.2.3\"></r>; Cremer, 156).</sy>"},"G1119":{"l":"γόνυ","o":12,"ar":"<f><o>γόνυ</o>، <g>-ατος, τό</g>، </f> <s><b>الركبة</b>: <r v=\"Heb.12.12\"></r>؛ عن المتضرّع، <g>προσπίπτειν τοῖς γ.</g>، <r v=\"Luke.5.8\"></r>؛ وكذلك <g>τιθέναι τὰ γ.</g>، <i>يجثو على ركبتيه</i>: <r v=\"Luke.22.41\"></r>، <r v=\"Acts.7.60\"></r> <r v=\"Acts.9.40\"></r> <r v=\"Acts.20.36\"></r> <r v=\"Acts.21.5\"></r>؛ استهزاءً، <r v=\"Mark.15.19\"></r>؛ <g>κάμπτειν τὰ γ.</g>، <i>يحني الركبة</i>: <r v=\"Rom.11.4\"></r> <i>(السبعينية)</i> <r v=\"Rom.14.11\"></r> <i>(السبعينية)</i>، <r v=\"Eph.3.14\"></r>، <r v=\"Phil.2.10\"></r>.†</s>","en":"<f><o>γόνυ</o>, <g>-ατος, τό</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1290\">בֶּרֶךְ</h> ;]</e> </et> <s><b>the knee</b>: <r v=\"Heb.12.12\"></r>; of a suppliant, <g>προσπίπτειν τοῖς γ.</g>, <r v=\"Luke.5.8\"></r>; so also <g>τιθέναι τὰ γ.</g>, <i>to kneel</i>: <r v=\"Luke.22.41\"></r>, <r v=\"Acts.7.60\"></r> <r v=\"Acts.9.40\"></r> <r v=\"Acts.20.36\"></r> <r v=\"Acts.21.5\"></r>; in mockery, <r v=\"Mark.15.19\"></r>; <g>κάμπτειν τὰ γ.</g>, <i>to bend the knee</i>: <r v=\"Rom.11.4\"></r> <i>(LXX)</i> <r v=\"Rom.14.11\"></r> <i>(LXX)</i>, <r v=\"Eph.3.14\"></r>, <r v=\"Phil.2.10\"></r>.†</s>"},"G1162":{"l":"δέησις","o":18,"ar":"<f><o>δέησις</o>، <g>-εως, ἡ</g></f> <s> <s n=\"1.\"><b>عَوَز، احتياج</b> (وهكذا في <r v=\"LXX:Ps.21.25\"></r>). </s> <s n=\"2.\"><b>طلب، توسّل، تضرّع</b>؛ وفي العهد الجديد موجَّهة دائمًا إلى الله: <r v=\"Luke.1.13\"></r>، <r v=\"2Cor.1.11\"></r>، <r v=\"Phil.1.19\"></r>، <r v=\"2Tim.1.3\"></r>، <r v=\"Jas.5.16\"></r>، <r v=\"1Pet.3.12\"></r> <i>(السبعينية)</i>؛ مع <g>νηστεῖαι</g>، <r v=\"Luke.2.37\"></r>؛ <g>προσυνχή, -αί</g>، <r v=\"Eph.6.18\"></r>، <r v=\"Phil.4.6\"></r>، <r v=\"1Tim.2.1\"></r> <r v=\"1Tim.5.5\"></r>؛ <g>ἱκετηρίαι</g>، <r v=\"Heb.5.7\"></r>؛ <g>προσκαρτέρησις</g>، <r v=\"Eph.6.18\"></r>؛ <g>ἐντεύξεις</g>، <r v=\"1Tim.2.1\"></r>؛ <g>δ. ποιεῖσθαι</g>، <r v=\"Luke.5.33\"></r>، <r v=\"Phil.1.4\"></r> (جمع)، <r v=\"1Tim.2.1\"></r>؛ يليه <g>ὑπέρ</g>، <r v=\"2Cor.9.14\"></r>، <r v=\"Phil.1.4\"></r>؛ <g>περί</g>، <r v=\"Eph.6.18\"></r>؛ <g>πρός</g>، <r v=\"Rom.10.1\"></r>.†</s> </s>","en":"<f><o>δέησις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>δέομαι</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H8467\">תְּחִנָּה</h>, <h n=\"H7440\">רִנָּה</h>, <h n=\"H8605\">תְּפִלָּה</h>, etc. ;]</e> </et> <s> <s n=\"1.\"><b>a wanting, need</b> (so <r v=\"LXX:Ps.21.25\"></r>). </s> <s n=\"2.\"><b>an asking, entreaty, supplica­tion</b>; in NT always addressed to God: <r v=\"Luke.1.13\"></r>, <r v=\"2Cor.1.11\"></r>, <r v=\"Phil.1.19\"></r>, <r v=\"2Tim.1.3\"></r>, <r v=\"Jas.5.16\"></r>, <r v=\"1Pet.3.12\"></r> <i>(LXX)</i>; with <g>νηστεῖαι</g>, <r v=\"Luke.2.37\"></r>; <g>προσυνχή, -αί</g>, <r v=\"Eph.6.18\"></r>, <r v=\"Phil.4.6\"></r>, <r v=\"1Tim.2.1\"></r> <r v=\"1Tim.5.5\"></r>; <g>ἱκετηρίαι</g>, <r v=\"Heb.5.7\"></r>; <g>προσκαρτέρησις</g>, <r v=\"Eph.6.18\"></r>; <g>ἐντεύξεις</g>, <r v=\"1Tim.2.1\"></r>; <g>δ. ποιεῖσθαι</g> (Deiss., <i>BS</i>, 250), <r v=\"Luke.5.33\"></r>, <r v=\"Phil.1.4\"></r> (pl.), <r v=\"1Tim.2.1\"></r>; seq. <g>ὑπέρ</g>, <r v=\"2Cor.9.14\"></r>, <r v=\"Phil.1.4\"></r>; <g>περί</g>, <r v=\"Eph.6.18\"></r>; <g>πρός</g>, <r v=\"Rom.10.1\"></r>.†</s> </s> <sy><i>SYN.</i>: <g>προσευχή</g>, used of <b>prayer</b> in general, while <g>δ.</g> gives prominence to the sense of need; on the other hand, <g>δ.</g> is used as well of requests from man to man, while <g>π.</g> is limited to prayer to God. <g>ἔντευξις</g>, in the papyri, is the regular word for <b>petition</b> to a superior (Deiss., <i>BS</i>, 250; cf. the Pauline <g>ἐντυγχάνειν</g>, <b>to entreat</b>). Cf. also <g>εὐχή</g>. (<r v=\"Jas.5.15\"></r>), <g>αἴτημα</g>, <g>ἱκετηρία</g> (Tr., <i>Syn.</i>, § li; Cremer, 73, 174, 684).</sy>"},"G1188":{"l":"δεξιός","o":54,"ar":"<f><o>δεξιός</o>، <g>-ά, -όν </g></f> <s><b>الأيمن (اليمين)</b>: <r v=\"Matt.5.29\"></r>، <r v=\"John.18.10\"></r>، وفي مواضع أخرى؛ <g>ὅπλα δ.</g>، أسلحة تُحمَل باليد اليمنى، أي للهجوم، <r v=\"2Cor.6.7\"></r>؛ <g>ἡ δ. χείρ</g>، <r v=\"Matt.5.30\"></r>، <r v=\"Luke.6.6\"></r>، وفي مواضع أخرى؛ <g>ἡ δ.</g> (أي <g>χείρ</g>)، <r v=\"Matt.6.3\"></r>، وفي مواضع أخرى؛ <g>ἐπὶ τὴν δ.</g>، <b>في اليد اليمنى</b>، <r v=\"Rev.5.1\"></r>؛ <g>διδόναι τὴν δ.</g>، علامةَ صداقة، <r v=\"Gal.2.9\"></r>؛ مجازيًا عن القوة، <g>τῇ δ. αὐτοῦ</g>، <r v=\"Acts.2.33\"></r> <r v=\"Acts.5.31\"></r>؛ <g>τὰ δ.</g>، <b>الجانب الأيمن</b>، <r v=\"Mark.16.5\"></r>؛ <g>ἐκ δεξιῶν</g>، <b>عن اليمين</b>، مع المضاف إليه، <r v=\"Matt.25.33\"></r>، <r v=\"Matt.25.34\"></r>، <r v=\"Mark.15.27\"></r>، <r v=\"Luke.1.11\"></r>، وفي مواضع أخرى؛ عن مكان الكرامة في الملكوت المسياني (قارن <r v=\"1Kgs.2.19\"></r>، <r v=\"Ps.45.10\"></r>)، <g>καθίσαι ἐκ δεξιῶν</g>، <r v=\"Matt.20.21\"></r>، <r v=\"Mark.10.37\"></r>؛ عن جلوس المسيح في السماء، <r v=\"Matt.26.64\"></r>، <r v=\"Mark.14.62\"></r>، <r v=\"Heb.1.13\"></r> </s>","en":"<f><o>δεξιός</o>, <g>-ά, -όν </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3225\">יָמִין</h> ;] </e> </et> <s><b>the right</b>: <r v=\"Matt.5.29\"></r>, <r v=\"John.18.10\"></r>, al.; <g>ὅπλα δ.</g>, weapons carried in the right hand, i.e. for offence, <r v=\"2Cor.6.7\"></r> ; <g>ἡ δ. χείρ</g>, <r v=\"Matt.5.30\"></r>, <r v=\"Luke.6.6\"></r>, al.; <g>ἡ δ.</g> (sc. <g>χείρ</g>), <r v=\"Matt.6.3\"></r>, al.; <g>ἐπὶ τὴν δ.</g>, <b>in the right hand</b> (R, txt., <i>on</i> R, mg.), <r v=\"Rev.5.1\"></r>; <g>διδόναι τὴν δ.</g>, in friend­ship (Deiss., <i>BS</i>, 251), <r v=\"Gal.2.9\"></r>; metaph. of power, <g>τῇ δ. αὐτοῦ</g>, <r v=\"Acts.2.33\"></r> <r v=\"Acts.5.31\"></r>; <g>τὰ δ.</g>, <b>the right side</b>, <r v=\"Mark.16.5\"></r>; <g>ἐκ δεξιῶν</g>, <b>on the right hand</b>, c. gen., <r v=\"Matt.25.33\"></r>, <r v=\"Matt.25.34\"></r>, <r v=\"Mark.15.27\"></r>, <r v=\"Luke.1.11\"></r>, al.; of a place of honour in the Messianic Kingdom (cf. <r v=\"1Kgs.2.19\"></r>, <r v=\"Ps.45.10\"></r>), <g>καθίσαι ἐκ δεξιῶν</g>, <r v=\"Matt.20.21\"></r>, <r v=\"Mark.10.37\"></r>; of the heavenly session of Christ, <r v=\"Matt.26.64\"></r>, <r v=\"Mark.14.62\"></r>, <r v=\"Heb.1.13\"></r> (Cremer, 172) </s>"},"G1135":{"l":"γυνή","o":215,"ar":"<f><o>γυνή</o>، <g>-αικός, ἡ</g>، </f> <s> <s n=\"1.\"><b>امرأة</b>، متزوجة أو غير متزوجة: <r v=\"Matt.11.11\"></r> <r v=\"Matt.14.21\"></r>، وفي مواضع أخرى؛ <g>ὕπανδρος γ.</g>، <r v=\"Rom.7.2\"></r>؛ <g>γ. χήρα</g>، <r v=\"Luke.4.26\"></r>؛ وفي النداء، <g>γύναι</g> لا تتضمن لومًا ولا قسوة، بل تُستعمل كثيرًا لفظَ احترام ومودة، <r v=\"Matt.15.28\"></r>، <r v=\"John.2.4\"></r>، <r v=\"John.4.21\"></r> <r v=\"John.19.26\"></r>. </s> <s n=\"2.\"><b>زوجة</b>: <r v=\"Matt.1.20\"></r>، <r v=\"1Cor.7.3\"></r>، <r v=\"1Cor.7.4\"></r> وفي مواضع أخرى؛ <g>γ. ἀπολύειν</g>، <r v=\"Mark.10.2\"></r>، وفي مواضع أخرى؛ <g>γ. ἔχειν</g> <r v=\"Mark.6.18\"></r>؛ <g>γ. λαβεῖν</g>، <r v=\"Mark.12.19\"></r>؛ <g>γ. γαμεῖν</g>، <r v=\"Luke.14.20\"></r>. </s> <s n=\"3.\"><b>شمّاسة</b>، <r v=\"1Tim.3.11\"></r>.</s> </s>","en":"<f><o>γυνή</o>, <g>-αικός, ἡ</g>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H802\">אִשָּׁה</h> ;]</e> </et> <s> <s n=\"1.\"><b>a woman</b>, married or unmarried: <r v=\"Matt.11.11\"></r> <r v=\"Matt.14.21\"></r>, al.; <g>ὕπανδρος γ.</g>, <r v=\"Rom.7.2\"></r>; <g>γ. χήρα</g>, <r v=\"Luke.4.26\"></r>; in vocat., <g>γύναι</g> implies neither reproof nor severity, but is used freq. as a term of respect and endearment, <r v=\"Matt.15.28\"></r>, <r v=\"John.2.4\"></r>, <r v=\"John.4.21\"></r> <r v=\"John.19.26\"></r>. </s> <s n=\"2.\"><b>a wife</b>: <r v=\"Matt.1.20\"></r>, <r v=\"1Cor.7.3\"></r>, <r v=\"1Cor.7.4\"></r> al.; <g>γ. ἀπολύειν</g>, <r v=\"Mark.10.2\"></r>, al.; <g>γ. ἔχειν</g> <r v=\"Mark.6.18\"></r>; <g>γ. λαβεῖν</g>, <r v=\"Mark.12.19\"></r>; <g>γ. γαμεῖν</g>, <r v=\"Luke.14.20\"></r>. </s> <s n=\"3.\"><b>a deaconess</b>, <r v=\"1Tim.3.11\"></r> (<i>CGT</i>, in l.).</s> </s>"},"G1127":{"l":"γρηγορέω","o":22,"ar":"<f><o>γρηγορέω</o>، <g>-ῶ</g>، = الأتيكية <g>ἐργήγορα</g>، التام من <g>ἐγείρω</g>، انظره، </f> <s> <s n=\"1.\"><b>يكون مستيقظًا، يسهر</b>؛ مجازيًا، عن كون الإنسان حيًّا، <r v=\"1Thess.5.10\"></r>. </s> <s n=\"2.\"><b>يسهر، يراقب</b>: <r v=\"Matt.24.43\"></r> <r v=\"Matt.26.38\"></r>، <r v=\"Matt.26.40\"></r> <r v=\"Mark.13.34\"></r> <r v=\"Mark.14.34\"></r>، <r v=\"Mark.14.37\"></r> <r v=\"Luke.12.37\"></r>، 39؛ مجازيًا، <r v=\"Matt.24.42\"></r> <r v=\"Matt.25.13\"></r> 26: 41، <r v=\"Mark.13.35\"></r>، 37 14: 38، <r v=\"Acts.20.31\"></r>، <r v=\"1Cor.16.13\"></r>، <r v=\"1Thess.5.6\"></r>، <r v=\"1Pet.5.8\"></r>، <r v=\"Rev.3.2\"></r>، <r v=\"Rev.3.3\"></r> <r v=\"Rev.16.15\"></r>؛ يليه <g>ἐν</g>، <r v=\"Col.4.2\"></r>. (قارن <g>δια-γρηγορέω</g>.)†</s> </s>","en":"<f><o>γρηγορέω</o>, <g>-ῶ</g>, = Attic <g>ἐργήγορα</g>, pf. of <g>ἐγείρω</g>, q.v., </f> <et> <e t=\"septuagint\">[in LXX (later bks. only) chiefly for <h n=\"H8245\">שׁקד</h> ;]</e> </et> <s> <s n=\"1.\"><b>to be awake</b>; metaph., of being alive, <r v=\"1Thess.5.10\"></r>. </s> <s n=\"2.\"><b>to watch</b>: <r v=\"Matt.24.43\"></r> <r v=\"Matt.26.38\"></r>, <r v=\"Matt.26.40\"></r> <r v=\"Mark.13.34\"></r> <r v=\"Mark.14.34\"></r>, <r v=\"Mark.14.37\"></r> <r v=\"Luke.12.37\"></r>, 39; metaph., <r v=\"Matt.24.42\"></r> <r v=\"Matt.25.13\"></r> 26:41, <r v=\"Mark.13.35\"></r>, 37 14:38, <r v=\"Acts.20.31\"></r>, <r v=\"1Cor.16.13\"></r>, <r v=\"1Thess.5.6\"></r>, <r v=\"1Pet.5.8\"></r>, <r v=\"Rev.3.2\"></r>, <r v=\"Rev.3.3\"></r> <r v=\"Rev.16.15\"></r>; seq. <g>ἐν</g>, <r v=\"Col.4.2\"></r>. (Cf. <g>δια-γρηγορέω</g>.†</s> </s> <sy><i>SYN.</i>: v.s. <g>ἀγρθπνέω</g>.</sy>"},"G1144":{"l":"δάκρυον","o":10,"ar":"<f><o>δάκρυον</o> <e t=\"derivation\">(وصيغته الشعرية <g>δάκρυ</g>)،</e> <g>-ου, τό</g>، </f> <s><b>دمعة</b>: <r v=\"Mark.9.24\"></r>، <r v=\"Acts.20.19\"></r>، <r v=\"Acts.20.31\"></r>، <r v=\"2Cor.2.4\"></r>، <r v=\"2Tim.1.4\"></r>، <r v=\"Heb.5.7\"></r> <r v=\"Heb.12.17\"></r>، <r v=\"Rev.7.17\"></r> <r v=\"Rev.21.4\"></r>؛ مجازيًا، القابل في الجمع، <g>δάκρυσι</g> (<r v=\"Lam.2.11\"></r>)، <r v=\"Luke.7.38\"></r>، <r v=\"Luke.7.44\"></r>.†</s>","en":"<f><o>δάκρυον</o> <e t=\"derivation\">(poët. form <g>δάκρυ</g>),</e> <g>-ου, τό</g>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1832\">דִּמְעָה</h> ;] </e> </et> <s><b>a tear</b>: <r v=\"Mark.9.24\"></r> (WH, txt., R, txt. omit), <r v=\"Acts.20.19\"></r>, <r v=\"Acts.20.31\"></r>, <r v=\"2Cor.2.4\"></r>, <r v=\"2Tim.1.4\"></r>, <r v=\"Heb.5.7\"></r> <r v=\"Heb.12.17\"></r>, <r v=\"Rev.7.17\"></r> <r v=\"Rev.21.4\"></r>; metaph., dat. pl., <g>δάκρυσι</g> (<r v=\"Lam.2.11\"></r>, Thuc., vii, 75; Bl., § 9, 3), <r v=\"Luke.7.38\"></r>, <r v=\"Luke.7.44\"></r>.†</s>"},"G1159":{"l":"δαπανάω","o":5,"ar":"<f>** <o>δαπανάω</o>، <g>-ῶ </g></f> <s n=\"1.\"><b>يُنفق، يصرف</b>: مع المنصوب، <r v=\"Mark.5.26\"></r>؛ يليه <g>ἐπί</g>، مع القابل للأشخاص، <r v=\"Acts.21.24\"></r>؛ <g>ὑπέρ</g>، <r v=\"2Cor.12.15\"></r>. </s> <s n=\"2.\"><b>يستهلك، يبدِّد</b>: <r v=\"Luke.15.14\"></r>؛ <g>ἐν τ. ἡδσναῖς</g>، <r v=\"Jas.4.3\"></r> (قارن <g>ἐκ-, προσ- δ.</g>).†</s>","en":"<f>** <o>δαπανάω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Tob.1.7\"></r>, <r v=\"1Macc.14.32\"></r>, al. ;]</e> </et> <s n=\"1.\"><b>to spend, expend</b>: c. acc., <r v=\"Mark.5.26\"></r>; seq. <g>ἐπί</g>, c. dat. pers., <r v=\"Acts.21.24\"></r>; <g>ὑπέρ</g>, <r v=\"2Cor.12.15\"></r>. </s> <s n=\"2.\"><b>to consume, squander</b>: <r v=\"Luke.15.14\"></r>; <g>ἐν τ. ἡδσναῖς</g> (on the constr. with <g>ἐν</g>, v. Hort, Mayor, in l.), <r v=\"Jas.4.3\"></r> (cf. <g>ἐκ-, προσ- δ.</g>).†</s>"},"G1103":{"l":"γνήσιος","o":4,"ar":"<f>** <o>γνήσιος</o>، <g>-α, -ον</g> </f> <s> <s n=\"1.\">أصلاً، <b>مولود ولادة شرعية، مولود من زواج</b>. </s> <s n=\"2.\"><b>حقيقي، أصيل، مخلص</b>: <r v=\"Phil.4.3\"></r>، <r v=\"1Tim.1.2\"></r>، <r v=\"Titus.1.4\"></r>؛ بمعنى الاسم، <g>τὸ γ.</g> = <g>ἡ γνησιότης</g>، <i>الإخلاص</i>، <r v=\"2Cor.8.8\"></r>.†</s> </s>","en":"<f>** <o>γνήσιος</o>, <g>-α, -ον</g> </f> <et> <e t=\"derivation\">(&lt; <g>γίγνομαι</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Sir.7.18\"></r>, <r v=\"3Macc.3.19\"></r> * ;]</e> </et> <s> <s n=\"1.\">prop., <b>lawfully begotten, born in wedlock</b> (in <g>π.</g>, <g>γυνὴ γ.</g>, <i>a lawful wife</i>; MM, s.v.). </s> <s n=\"2.\"><b>true, genuine, sincere</b>: <r v=\"Phil.4.3\"></r>, <r v=\"1Tim.1.2\"></r>, <r v=\"Titus.1.4\"></r>; as subst., <g>τὸ γ.</g> = <g>ἡ γνησιότης</g>, <i>sincerity</i>, <r v=\"2Cor.8.8\"></r>.†</s> </s>"},"G1154":{"l":"Δαμασκός","o":15,"ar":"<f><o>Δαμασκός</o>، <g>-οῦ, ἡ</g> (العبرية <h n=\"H1834\">דַּמֶּשֶׂק</h>)، </f> <s><b>دمشق</b>: <r v=\"Acts.9.2\"></r> وما يليه <r v=\"Acts.22.5\"></r> وما يليه <r v=\"Acts.26.12\"></r>، <r v=\"Acts.26.20\"></r>، <r v=\"2Cor.11.32\"></r>، <r v=\"Gal.1.17\"></r>.†</s>","en":"<f><o>Δαμασκός</o>, <g>-οῦ, ἡ</g> (Heb. <h n=\"H1834\">דַּמֶּשֶׂק</h>), </f> <s><b>Damascus</b>: <r v=\"Acts.9.2\"></r>ff. <r v=\"Acts.22.5\"></r>ff. <r v=\"Acts.26.12\"></r>, <r v=\"Acts.26.20\"></r>, <r v=\"2Cor.11.32\"></r>, <r v=\"Gal.1.17\"></r>.†</s>"},"G1138":{"l":"Δαυείδ","o":54,"ar":"<f><o>Δαυείδ</o>، <g>ὁ</g>، لا يُصرَّف (العبرية <h n=\"H1732\">דָּוִד</h>)، </f> <s><b>داود</b>، ملك إسرائيل: <r v=\"Matt.1.6\"></r>؛ <r v=\"Matt.12.3\"></r>، وفي مواضع أخرى؛ <g>σκηνὴ Δ.</g>، <r v=\"Acts.15.16\"></r>؛ <g>κλεὶς Δ.</g>، <r v=\"Rev.3.7\"></r>؛ <g>θρόνος Δ.</g>، <r v=\"Luke.1.32\"></r>؛ <g>ῥίζα Δ.</g>، <r v=\"Rev.5.5\"></r>؛ <g>βασιλεία Δ.</g>، <r v=\"Mark.11.10\"></r>؛ <g>υἱὸς Δ.</g>، أي المسيّا (<r v=\"PsSol.17.23\"></r>)، <r v=\"Matt.1.1\"></r>، <r v=\"Matt.9.27\"></r>، وفي مواضع أخرى؛ <g>ἐν Δ.</g>، أي سفر المزامير، <r v=\"Heb.4.7\"></r> </s>","en":"<f><o>Δαυείδ</o> (Rec. <g>Δαβίδ</g>), <g>ὁ</g>, indecl. (Heb. <h n=\"H1732\">דָּוִד</h>), </f> <s><b>David</b>, King of Israel: <r v=\"Matt.1.6\"></r>; <r v=\"Matt.12.3\"></r>, et al.; <g>σκηνὴ Δ.</g>, <r v=\"Acts.15.16\"></r>; <g>κλεὶς Δ.</g>, <r v=\"Rev.3.7\"></r>; <g>θρόνος Δ.</g>, <r v=\"Luke.1.32\"></r>; <g>ῥίζα Δ.</g>, <r v=\"Rev.5.5\"></r>; <g>βασιλεία Δ.</g>, <r v=\"Mark.11.10\"></r>; <g>υἱὸς Δ.</g>, the Messiah (<r v=\"PsSol.17.23\"></r>; for other reff. in Jewish lit., v. Dalman, <i>Words</i>, 317), <r v=\"Matt.1.1\"></r> <r v=\"Matt.9.27\"></r>, et al.; <g>ἐν Δ.</g>, i.e. the Psalter, <r v=\"Heb.4.7\"></r> </s>"},"G1167":{"l":"δειλία","o":1,"ar":"<f><o>δειλία</o>، <g>-ας, ἡ</g> </f> <s><b>جُبن، فشل</b> (ولا يأتي قط بمعنى حسن): <r v=\"2Tim.1.7\"></r>.†</s>","en":"<f><o>δειλία</o>, <g>-ας, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>δειλός</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H367\">אֵימָה</h>, <h n=\"H4288\">מְחִתָּה</h>, etc. ;] </e> </et> <s><b>cowardice, timidity</b> (never in good sense): <r v=\"2Tim.1.7\"></r>.†</s> <sy><i>SYN.</i>: <g>φόβος</g>, <b>fear</b>, in general, good or bad; <g>εὐλάβεια</g> (q.v.), apprehension generally, but chiefly <b>pious fear</b>, \"that careful and watchful reverence which pays regard to every circumstance in that with which it has to deal\" (cf. Tr., <i>Syn.</i>, § x).†</sy>"},"G1129":{"l":"γυμνασία","o":1,"ar":"<f>** <o>γυμνασία</o>، <g>-ας, ἡ</g> </f> <s><b>رياضة، تدريب</b>: <r v=\"1Tim.4.8\"></r>.†</s>","en":"<f>** <o>γυμνασία</o>, <g>-ας, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γυμνάζω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.11.20\"></r> * ;]</e> </et> <s><b>exercise</b>: <r v=\"1Tim.4.8\"></r>.†</s>"},"G1130":{"l":"γυμνιτεύω","o":1,"ar":"<f>*† <o>γυμνιτεύω</o>، </f> <s><b>كان عريانًا</b> أو <b>قليل الكسوة</b>: <r v=\"1Cor.4.11\"></r> (قارن <g>ἐν ψύχει κ. γυμνότητι</g>: <r v=\"2Cor.11.27\"></r>؛ <g>γυμνοί</g>: <r v=\"Jas.2.15\"></r>). وعند الكتّاب المتأخرين (<g>κοινή</g>) يعني <g>γ.</g> أيضًا <b>سار خفيف السلاح</b>.†</s>","en":"<f>*† <o>γυμνιτεύω</o> (Rec. <g>γυμνητ-</g>, V. Tdf ., <i>Pr.</i>, 81), </f> <s><b>to be naked</b> or <b>scantily clad</b>: <r v=\"1Cor.4.11\"></r> (cf. <g>ἐν ψύχει κ. γυμνότητι</g>, <r v=\"2Cor.11.27\"></r>; <g>γυμνοί</g>, <r v=\"Jas.2.15\"></r>. In <g>κοινή</g> writers, <g>γ.</g> also means <b>to go light-armed</b>.†</s>"},"G1165":{"l":"δειγματίζω","o":2,"ar":"<f>*† <o>δειγματίζω</o> </f> <s>كلمة نادرة: <b>شهّر، فضح علانيةً</b>: <r v=\"Matt.1.19\"></r>، <r v=\"Col.2.15\"></r>.†</s>","en":"<f>*† <o>δειγματίζω</o> </f> <et> <e t=\"derivation\">(&lt; <g>δεῖγμα</g>), </e> </et> <s>a rare word (<i>ICC</i>, ll. c.), <b>to make a show of, to expose</b>: <r v=\"Matt.1.19\"></r> (Rec. <g>παραδ-</g>, q.v.), <r v=\"Col.2.15\"></r>.†</s>"},"G1100":{"l":"γλῶσσα","o":50,"ar":"<f><o>γλῶσσα</o>، <g>-ης, ἡ</g>، </f> <s> <s n=\"1.\"><b>اللسان</b>، بوصفه عضو النطق: <r v=\"Mark.7.33\"></r>، <r v=\"Mark.7.35\"></r> <r v=\"Luke.1.64\"></r> <r v=\"Luke.16.24\"></r>، <r v=\"Acts.2.26\"></r> <i>(السبعينية)</i>، <r v=\"Rom.3.13\"></r> <i>(السبعينية)</i> <r v=\"Rom.14.11\"></r> <i>(السبعينية)</i>، <r v=\"1Cor.14.9\"></r>، <r v=\"Phil.2.11\"></r>، <r v=\"Jas.1.26\"></r> <r v=\"Jas.3.5\"></r>، <r v=\"Jas.3.6\"></r>، <r v=\"Jas.3.8\"></r>، <r v=\"1Pet.3.10\"></r> <i>(السبعينية)</i>، <r v=\"1John.3.18\"></r>، <r v=\"Rev.16.10\"></r>؛ عن شيء يشبه اللسان، <r v=\"Acts.2.3\"></r>. </s> <s n=\"2.\"><b>لسان، لغة</b>: <r v=\"Acts.2.11\"></r>؛ مقرونًا بـ <g>φυλή, λαός, ἔθνος</g>، كثيرًا في الجمع، <r v=\"Rev.5.9\"></r> <r v=\"Rev.7.9\"></r> <r v=\"Rev.10.11\"></r> <r v=\"Rev.11.9\"></r> <r v=\"Rev.13.7\"></r> <r v=\"Rev.14.6\"></r> <r v=\"Rev.17.15\"></r>؛ <g>λαλεῖν ἑτέραις γ.</g>، <r v=\"Acts.2.4\"></r>؛ <g>γ. λαλεῖν καιναῖς</g>، <r v=\"Mark.16.17\"></r>؛ <g>λαλεῖν γλώσσαις, γλώσσῃ</g>، <r v=\"Mark.16.17\"></r>، <r v=\"Acts.10.46\"></r> <r v=\"Acts.19.6\"></r>، <r v=\"1Cor.12.30\"></r> <r v=\"1Cor.13.1\"></r> <r v=\"1Cor.14.2\"></r>، <r v=\"1Cor.14.4-1Cor.14.6\"></r>، <r v=\"1Cor.14.13\"></r>، <r v=\"1Cor.14.18\"></r>، <r v=\"1Cor.14.23\"></r>، <r v=\"1Cor.14.27\"></r>، <r v=\"1Cor.14.39\"></r>؛ <g>γλῶσσαι</g> (= <g>λόγοι ἐν γλώσσῃ</g>، <r v=\"1Cor.14.19\"></r>)، <r v=\"1Cor.13.8\"></r> <r v=\"1Cor.14.22\"></r>؛ <g>γένη γλωσσῶν</g>، <r v=\"1Cor.12.10\"></r>، <r v=\"1Cor.12.28\"></r>؛ <g>προσεύχεσθαι γλώσσῃ</g>، <r v=\"1Cor.14.14\"></r>؛ <g>γλῶσσαν ἔχειν</g>، <r v=\"1Cor.14.26\"></r>.†</s> </s>","en":"<f><o>γλῶσσα</o>, <g>-ης, ἡ</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3956\">לָשׁוֹן</h> ;]</e> </et> <s> <s n=\"1.\"><b>the tongue</b>, as the organ of speech: <r v=\"Mark.7.33\"></r>, <r v=\"Mark.7.35\"></r> <r v=\"Luke.1.64\"></r> <r v=\"Luke.16.24\"></r>, <r v=\"Acts.2.26\"></r> <i>(LXX)</i>, <r v=\"Rom.3.13\"></r> <i>(LXX)</i> <r v=\"Rom.14.11\"></r> <i>(LXX)</i>, <r v=\"1Cor.14.9\"></r>, <r v=\"Phil.2.11\"></r>, <r v=\"Jas.1.26\"></r> <r v=\"Jas.3.5\"></r>, <r v=\"Jas.3.6\"></r>, <r v=\"Jas.3.8\"></r>, <r v=\"1Pet.3.10\"></r> <i>(LXX)</i>, <r v=\"1John.3.18\"></r>, <r v=\"Rev.16.10\"></r>; of a tongue-like object, <r v=\"Acts.2.3\"></r>. </s> <s n=\"2.\"><b>a tongue, language</b>: <r v=\"Acts.2.11\"></r>; joined with <g>φυλή, λαός, ἔθνος</g>, freq. in pl., <r v=\"Rev.5.9\"></r> <r v=\"Rev.7.9\"></r> <r v=\"Rev.10.11\"></r> <r v=\"Rev.11.9\"></r> <r v=\"Rev.13.7\"></r> <r v=\"Rev.14.6\"></r> <r v=\"Rev.17.15\"></r>; <g>λαλεῖν ἑτέραις γ.</g>, <r v=\"Acts.2.4\"></r>; <g>γ. λαλεῖν καιναῖς</g>, WH, txt. (RV, mg., omit <g>καιναῖς</g>), <r v=\"Mark.16.17\"></r>; <g>λαλεῖν γλώσσαις, γλώσσῃ</g> (v. <i>ICC</i>, ll. c.; <i>DB</i>, iv, 793ff.), <r v=\"Mark.16.17\"></r>, WH, txt., R, mg., <r v=\"Acts.10.46\"></r> <r v=\"Acts.19.6\"></r>, <r v=\"1Cor.12.30\"></r> <r v=\"1Cor.13.1\"></r> <r v=\"1Cor.14.2\"></r>, <r v=\"1Cor.14.4-1Cor.14.6\"></r>, <r v=\"1Cor.14.13\"></r>, <r v=\"1Cor.14.18\"></r>, <r v=\"1Cor.14.23\"></r>, <r v=\"1Cor.14.27\"></r>, <r v=\"1Cor.14.39\"></r>; <g>γλῶσσαι</g> (= <g>λόγοι ἐν γλώσσῃ</g>, <r v=\"1Cor.14.19\"></r>), <r v=\"1Cor.13.8\"></r> <r v=\"1Cor.14.22\"></r>; <g>γένη γλωσσῶν</g>, <r v=\"1Cor.12.10\"></r>, <r v=\"1Cor.12.28\"></r>; <g>προσεύχεσθαι γλώσσῃ</g>, <r v=\"1Cor.14.14\"></r>; <g>γλῶσσαν ἔχειν</g>, <r v=\"1Cor.14.26\"></r> (Cremer, 163, 679).†</s> </s>"},"G1124":{"l":"γραφή","o":50,"ar":"<f><o>γραφή</o>، <g>-ῆς, ἡ</g> </f> <s> <s n=\"1.\"><b>رسم، تصوير</b>. </s> <s n=\"2.\"> <s n=\"(a)\"><b>كتابة</b>؛ </s> <s n=\"(b)\"><b>المكتوب، كتاب</b>: <g>πᾶσα γ.</g>، <r v=\"2Tim.3.16\"></r>؛ <g>γ. ἅγιαι</g>، <r v=\"Rom.1.2\"></r>؛ <g>προφητικαί</g>، <r v=\"Rom.16.26\"></r>؛ <g>αἱ γ. τ. προφητῶν</g>، <r v=\"Matt.26.56\"></r>؛ <g>ἡ γ., αἱ γ.</g>، <i>الكتابات المقدسة، الكتب</i> (أي العهد القديم)؛ في الجمع حين يُقصد الكتب المقدسة ككل، مثلاً <r v=\"Matt.21.42\"></r> <r v=\"Matt.26.54\"></r>، <r v=\"John.5.39\"></r>، <r v=\"Rom.15.4\"></r>؛ وفي المفرد حين يُشار إلى فقرة معيّنة، كما في <r v=\"Luke.4.21\"></r>، <r v=\"John.19.24\"></r>، <r v=\"Rom.4.3\"></r> <r v=\"Rom.9.17\"></r> <r v=\"Rom.10.11\"></r> <r v=\"Rom.11.2\"></r>، <r v=\"Jas.2.23\"></r>.</s> </s> </s>","en":"<f><o>γραφή</o>, <g>-ῆς, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γράφω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3791\">כְּתָב</h> ;]</e> </et> <s> <s n=\"1.\"><b>a drawing, painting</b>. </s> <s n=\"2.\"> <s n=\"(a)\"><b>writing</b>; </s> <s n=\"(b)\"><b>that which is written, a writing</b>: <g>πᾶσα γ.</g>, <r v=\"2Tim.3.16\"></r>; <g>γ. ἅγιαι</g>, <r v=\"Rom.1.2\"></r>; <g>προφητικαί</g>, <r v=\"Rom.16.26\"></r>; al <g>αἱ γ. τ. προφητῶν</g>, <r v=\"Matt.26.56\"></r>; <g>ἡ γ., αἱ γ.</g>, <i>the sacred writings, the Scriptures</i> (i.e. the OT; v. Milligan, <i>NTD</i>, 205); in pl., when the sacred writings as a whole are meant, e.g. <r v=\"Matt.21.42\"></r> <r v=\"Matt.26.54\"></r>, <r v=\"John.5.39\"></r>, <r v=\"Rom.15.4\"></r>; in sing., when a particular passage is referred to, as in <r v=\"Luke.4.21\"></r>, <r v=\"John.19.24\"></r>, <r v=\"Rom.4.3\"></r> <r v=\"Rom.9.17\"></r> <r v=\"Rom.10.11\"></r> <r v=\"Rom.11.2\"></r>, <r v=\"Jas.2.23\"></r> (Cremer, 165; <i>DCG</i>, ii, 584).</s> </s> </s>"},"G1194":{"l":"δέρω","o":15,"ar":"<f><o>δέρω </o></f> <s n=\"1.\"><b>سلخ، نزع الجلد</b>. </s> <s n=\"2.\"><b>ضرب، جلد</b>: مع المنصوب، <r v=\"Matt.21.35\"></r>، <r v=\"Mark.12.3\"></r>، <r v=\"Mark.12.5\"></r>، <r v=\"Luke.20.10\"></r>، <r v=\"Luke.20.11\"></r> <r v=\"Luke.22.63\"></r>، <r v=\"John.18.23\"></r>، <r v=\"Acts.5.40\"></r> <r v=\"Acts.16.37\"></r> <r v=\"Acts.22.19\"></r>؛ <g>ὡς ἀέρα δέρων</g>، <r v=\"1Cor.9.26\"></r>؛ <g>εἰς πρόσωπου δ.</g>، <r v=\"2Cor.11.20\"></r>. المبني للمجهول، <r v=\"Mark.13.9\"></r>، <r v=\"Luke.12.47\"></r>، <r v=\"Luke.12.48\"></r> (<g>δαρήσεται πολλάς, ὀλίγας</g>، أي <g>πληγάς</g>).†</s>","en":"<f><o>δέρω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Lev.1.6\"></r>, <r v=\"2Chr.29.34\"></r> <r v=\"2Chr.35.11\"></r> (<h n=\"H6584\">פָּשַׁט</h> hi.)* ;]</e> </et> <s n=\"1.\"><b>to skin, flay</b>. </s> <s n=\"2.\">(of. Eng. slang, <b>hide</b>) <b>to beat, thrash</b>: c. acc, <r v=\"Matt.21.35\"></r>, <r v=\"Mark.12.3\"></r>, <r v=\"Mark.12.5\"></r>, <r v=\"Luke.20.10\"></r>, <r v=\"Luke.20.11\"></r> <r v=\"Luke.22.63\"></r>, <r v=\"John.18.23\"></r>, <r v=\"Acts.5.40\"></r> <r v=\"Acts.16.37\"></r> <r v=\"Acts.22.19\"></r>; <g>ὡς ἀέρα δέρων</g>, <r v=\"1Cor.9.26\"></r>; <g>εἰς πρόσωπου δ.</g>, <r v=\"2Cor.11.20\"></r>. Pass., <r v=\"Mark.13.9\"></r>, <r v=\"Luke.12.47\"></r>, <r v=\"Luke.12.48\"></r> (<g>δαρήσεται πολλάς, ὀλίγας</g>, sc. <g>πληγάς</g>).†</s>"},"G1114":{"l":"γόης","o":1,"ar":"<f>* <o>γόης</o>، <g>-ητος, ὁ</g> (من <g>γοάω</g>، <i>ناح</i>)، </f> <s> <s n=\"1.\"><b>نائح</b>. </s> <s n=\"2.\"><b>ساحر</b>. </s> <s n=\"3.\"><b>دجّال، مُضِلّ</b> (قارن <g>γοητεία</g>، <i>الخداع</i>، <r v=\"2Macc.12.24\"></r>): <r v=\"2Tim.3.13\"></r>.†</s> </s>","en":"<f>* <o>γόης</o>, <g>-ητος, ὁ</g> (<g>γοάω</g>, <i>to wail</i>), </f> <s> <s n=\"1.\"><b>a wailer</b>. </s> <s n=\"2.\"><b>a wizard</b>. </s> <s n=\"3.\"><b>an impostor</b> (cf. <g>γοητεία</g>, <i>trickery</i>, <r v=\"2Macc.12.24\"></r>): <r v=\"2Tim.3.13\"></r>.†</s> </s>"},"G1184":{"l":"δεκτός","o":5,"ar":"<f>† <o>δεκτός</o>، <g>-ή, -όν </g></f> صفة فعلية <s><b>مقبول</b>: <r v=\"Luke.4.19\"></r> <i>(السبعينية)</i> <r v=\"Luke.4.24\"></r>، <r v=\"Acts.10.35\"></r>، <r v=\"2Cor.6.2\"></r> <i>(السبعينية)</i>، <r v=\"Phil.4.18\"></r> (قارن <g>εὐπροσδ-</g>).†</s>","en":"<f>† <o>δεκτός</o>, <g>-ή, -όν </g></f> verbal adj. <et> <e t=\"derivation\">of <g>δέχομαι</g>, </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7522\">רָצוֹן</h>: <r v=\"Prov.11.1\"></r>, al. ;]</e> </et> <s><b>acceptable</b>: <r v=\"Luke.4.19\"></r> <i>(LXX)</i> <r v=\"Luke.4.24\"></r>, <r v=\"Acts.10.35\"></r>, <r v=\"2Cor.6.2\"></r> <i>(LXX)</i>, <r v=\"Phil.4.18\"></r> (cf. <g>εὐπροσδ-</g>).†</s>"},"G1133":{"l":"γυναικάριον","o":1,"ar":"<f>* <o>γυναικάριον</o>، <g>-ου, τό</g> (تصغير <g>γυνή</g>)، </f> <s><b>امرأة صغيرة</b>؛ على سبيل الازدراء، <b>امرأة سخيفة (نُسَيّة)</b>: <r v=\"2Tim.3.6\"></r>.†</s>","en":"<f>* <o>γυναικάριον</o>, <g>-ου, τό</g> (dim. of <g>γυνή</g>), </f> <s><b>a little woman</b>; contemptuously, <b>a silly woman</b> (EV): <r v=\"2Tim.3.6\"></r>.†</s>"},"G1140":{"l":"δαιμόνιον","o":63,"ar":"<f><o>δαιμόνιον</o>، <g>-ου, τό</g></f> <s n=\"1.\">كما في الكلاسيكية؛ </s> <s n=\"(a)\">في اليونانية الكلاسيكية: <b>القوة الإلهية، الألوهية</b>؛ </s> <s n=\"(b)\"><b>إله أدنى، معبود</b> أو <b>شيطان</b>: <g>ξένα δ.</g>، <r v=\"Acts.17.18\"></r>. </s> <s n=\"2.\">(a) في العهد القديم: الآلهة الوثنية، الآلهة الكاذبة (مثلاً <r v=\"Deut.32.17\"></r>، <r v=\"LXX:Ps.95.5\"></r>)؛ </s> <s n=\"(b)\">في العهد الجديد: <b>أرواح شريرة، شياطين</b>: <g>θύουσιν δαιμονίοις</g>، <r v=\"1Cor.10.20\"></r>؛ <g>διδασκαλίαι δαιμονίων</g>، <r v=\"1Tim.4.1\"></r>؛ <g>προσκυνεῖν τὰ δ.</g>، <r v=\"Rev.9.20\"></r>؛ <g>ἄρχων τῶν δ.</g>، <r v=\"Matt.9.34\"></r>؛ وخاصةً (مرادفًا لـ <g>πνεῦμα ἀκάθαρτον</g>) بوصفها تعمل في البشر و«تسكنهم» (قارن <g>δαιμονίζομαι</g>): <r v=\"Matt.11.18\"></r>، وفي مواضع أخرى؛ <g>εἰσέρχεσθαι δ. εἰς</g>...، <r v=\"Luke.8.30\"></r>؛ <g>δ. ἔχειν</g>، <r v=\"Luke.4.33\"></r>؛ <g>δ. ἐκβάλλειν</g>، <r v=\"Matt.7.22\"></r>. وفي عبارة <g>πνεῦμα δαιμονίου ἀκαθάρτου</g>، <r v=\"Luke.4.33\"></r>، يظهر المعنى الكلاسيكي الأوسع (1. b)، إذ إن <g>ἀκ.</g> في سائر العهد الجديد صفةٌ لـ <g>πν.</g>، و<g>δ.</g> = <g>πν. ἀκ.</g>. </s>","en":"<f><o>δαιμόνιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(neut. of <g>δαιμόνιος, -α, -ον</g>, <i>divine</i>), </e> <e t=\"septuagint\">[in LXX (so also in <g>π</g>; v. MM, <i>Exp.</i>, x) for <h n=\"H7700\">שֵׁד</h>, <h n=\"H457\">אֱלִיל</h>, (freq. in Tob) ;] </e> </et> <s n=\"1.\">as in cl.; </s> <s n=\"(a)\"><b>the Divine power, Deity</b> (Hdt., Plat., al.); </s> <s n=\"(b)\"><b>an inferior divinity, deity</b> or <b>demon</b> (as in magical <g>π</g>, Deiss., <i>BS</i>, 281; MM, <i>Exp.</i>, x): <g>ξένα δ.</g>, <r v=\"Acts.17.18\"></r>. </s> <s n=\"2.\">(a) in OT, heathen deities, false gods (e.g. <r v=\"Deut.32.17\"></r>, <r v=\"LXX:Ps.95.5\"></r>); </s> <s n=\"(b)\">in NT, <b>evil spirits, demons</b>: <g>θύουσιν δαιμονίοις</g>, <r v=\"1Cor.10.20\"></r>; <g>διδασκαλίαι δαιμονίων</g>, <r v=\"1Tim.4.1\"></r>; <g>προσκυνεῖν τὰ δ.</g>, <r v=\"Rev.9.20\"></r>; <g>ἄρχων τῶν δ.</g>, <r v=\"Matt.9.34\"></r>; especially (syn. with <g>πνεῦμα ἀκάθαρτον</g>) as operating upon and \"possessing\" (of. <g>δαιμονίζομαι</g>) men: <r v=\"Matt.11.18\"></r>, et al.; <g>εἰσέρχεσθαι δ. εἰς</g>. . ., <r v=\"Luke.8.30\"></r>; <g>δ. ἔχειν</g>, <r v=\"Luke.4.33\"></r>; <g>δ. ἐκβάλλειν</g>, <r v=\"Matt.7.22\"></r> In the phrase <g>πνεῦμα δαιμονίου ἀκαθάρτου</g>, <r v=\"Luke.4.33\"></r>, the wider cl. usage (1. <i>b</i>) is recognised, <g>ἀκ.</g> being elsewhere in NT, the epithet of <g>πν.</g>, and <g>δ.</g> = <g>πν. ἀκ.</g> (v. <i>ICC</i>, in l; Cremer, 168) </s>"},"G1189":{"l":"δέομαι","o":12,"ar":"<f><o>δέομαι</o> </f> <s><b>يحتاج لنفسه</b>؛ </s> <s n=\"1.\"><b>يعوزه، يحتاج</b>: <s n=\"(a)\">مطلقًا؛ </s> <s n=\"(b)\">مع المضاف إليه. </s> </s> <s n=\"2.\"><b>يطلب، يلتمس، يتوسّل، يتضرّع</b>؛ <s n=\"(i)\">عمومًا: مطلقًا، <r v=\"Acts.26.3\"></r>؛ مع المضاف إليه للشخص، <r v=\"Luke.5.12\"></r>، <r v=\"Luke.8.28\"></r>، <r v=\"Luke.8.38\"></r>، <r v=\"Luke.9.38\"></r>، <r v=\"Acts.8.34\"></r>، <r v=\"Acts.21.39\"></r>، <r v=\"2Cor.5.20\"></r>، <r v=\"Gal.4.12\"></r>؛ يليه <g>ἵνα</g>، <r v=\"Luke.9.40\"></r>؛ يليه <g>τό</g> مع المصدر، <r v=\"2Cor.10.2\"></r>؛ مع المضاف إليه للشخص وللشيء، <r v=\"2Cor.8.4\"></r>؛ </s> <s n=\"(ii)\">عن الصلاة إلى الله: مطلقًا، <r v=\"Acts.4.31\"></r>؛ يليه <g>εἴ πως</g>، <r v=\"Rom.1.10\"></r>؛ <g>ἵνα</g>، <r v=\"Luke.21.36\"></r>، <r v=\"Luke.22.32\"></r>؛ <g>εἰς τό</g>، <r v=\"1Thess.3.10\"></r>؛ <g>ὑπὲρ ἐμοῦ πρὸς τ. κύριον, ὅπως</g>، <r v=\"Acts.8.24\"></r>؛ مع المضاف إليه، <g>τοῦ κυρίου, ὅπως</g>، <r v=\"Matt.9.38\"></r>، <r v=\"Luke.10.2\"></r>؛ <g>τοῦ Θεοῦ</g>، <r v=\"Acts.10.2\"></r>؛ يليه <g>εἰ ἄρα</g>، <r v=\"Acts.8.22\"></r>.† </s> </s>","en":"<f><o>δέομαι</o> </f> <et> <e t=\"derivation\">(mid. of <g>δέω</g>, II, q.v., as depon.) </e> <e t=\"septuagint\">[in LXX for <h n=\"H2603\">חנן</h>, etc. ;] </e> </et> <s><b>to want for oneself</b>; </s> <s n=\"1.\"><b>to want, need</b>: <s n=\"(a)\">absol.; </s> <s n=\"(b)\">c. gen. </s> </s> <s n=\"2.\"><b>to beg, request, beseech, pray</b>; <s n=\"(i)\">in general: absol., <r v=\"Acts.26.3\"></r>, WH; c. gen. pers., <r v=\"Luke.5.12\"></r> <r v=\"Luke.8.28\"></r>, <r v=\"Luke.8.38\"></r> (<g>ἐδεῖτο</g>; T, <g>ἐδέετο</g>, cf. Veitch, s.v. <g>δέω</g>) <r v=\"Luke.9.38\"></r>, <r v=\"Acts.8.34\"></r> <r v=\"Acts.21.39\"></r>, <r v=\"2Cor.5.20\"></r>, <r v=\"Gal.4.12\"></r>; seq. <g>ἵνα</g>, <r v=\"Luke.9.40\"></r>; seq. <g>τό</g>, c. inf., <r v=\"2Cor.10.2\"></r>; c. gen. pers. et rei, <r v=\"2Cor.8.4\"></r>; </s> <s n=\"(ii)\">of prayer to God: absol., <r v=\"Acts.4.31\"></r>; seq. <g>εἴ πως</g>, <r v=\"Rom.1.10\"></r>; <g>ἵνα</g>, <r v=\"Luke.21.36\"></r> <r v=\"Luke.22.32\"></r>; <g>εἰς τό</g>, <r v=\"1Thess.3.10\"></r>; <g>ὑπὲρ ἐμοῦ πρὸς τ. κύριον, ὅπως</g>, <r v=\"Acts.8.24\"></r>; c. gen., <g>τοῦ κυρίου, ὅπως</g>, <r v=\"Matt.9.38\"></r>, <r v=\"Luke.10.2\"></r>; <g>τοῦ Θεοῦ</g>, <r v=\"Acts.10.2\"></r>; seq. <g>εἰ ἄρα</g>, <r v=\"Acts.8.22\"></r>.† </s> </s> <sy><i>SYN.</i>: <g>αἰτέω</g>, and cf. <g>δέησις</g>.</sy>"},"G1173":{"l":"δεῖπνον","o":16,"ar":"<f><o>δεῖπνον</o>، <g>-ου, τό </g></f> <s>الوجبة الرئيسية في اليوم: <b>عشاء، وليمة</b>: <r v=\"Matt.23.6\"></r>، <r v=\"Mark.12.39\"></r>، <r v=\"Luke.14.17\"></r>، <r v=\"Luke.14.24\"></r>، <r v=\"Luke.20.46\"></r>، <r v=\"John.13.2\"></r>، <r v=\"John.13.4\"></r>، <r v=\"John.21.20\"></r>، <r v=\"1Cor.11.21\"></r>؛ <g>δ. ποιεῖν</g>، <r v=\"Mark.6.21\"></r>، <r v=\"Luke.14.12\"></r>، <r v=\"Luke.14.16\"></r>، <r v=\"John.12.2\"></r>؛ <g>κυριακὸν</g> (انظره) <g>δ.</g>، <r v=\"1Cor.11.20\"></r>؛ مجازيًا، <g>δ. τ. γάμου τ. ἀρνίου</g>، <r v=\"Rev.19.9\"></r>؛ <g>δ. τ. μέγα τ. Θεοῦ</g>، <r v=\"Rev.19.17\"></r>.†</s>","en":"<f><o>δεῖπνον</o>, <g>-ου, τό </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6598\">פַּת־בַּג</h> (Da) ;] </e> </et> <s>the chief meal of the day, <b>dinner, supper</b>: <r v=\"Matt.23.6\"></r>, <r v=\"Mark.12.39\"></r>, <r v=\"Luke.14.17\"></r>, <r v=\"Luke.14.24\"></r> <r v=\"Luke.20.46\"></r>, <r v=\"John.13.2\"></r>, <r v=\"John.13.4\"></r> <r v=\"John.21.20\"></r>, <r v=\"1Cor.11.21\"></r>; <g>δ. ποιεῖν</g>, <r v=\"Mark.6.21\"></r>, <r v=\"Luke.14.12\"></r>, <r v=\"Luke.14.16\"></r>, <r v=\"John.12.2\"></r>; <g>κυριακὸν</g> (q.v.) <g>δ.</g>, <r v=\"1Cor.11.20\"></r>; metaph. (Dalman, <i>Words</i>, 118), <g>δ. τ. γάμου τ. ἀρνίου</g>, <r v=\"Rev.19.9\"></r>; <g>δ. τ. μέγα τ. Θεοῦ</g>, <r v=\"Rev.19.17\"></r>.†</s>"},"G1149":{"l":"Δαλματία","o":1,"ar":"<f><o>Δαλματία</o>، <g>-ας, ἡ</g> </f> <s><b>دلماطية</b>، جزء من إلّيريكون على الساحل الشرقي للبحر الأدرياتيكي: <r v=\"2Tim.4.10\"></r>.†</s>","en":"<f><o>Δαλματία</o> (L, <g>Δελ-</g>), <g>-ας, ἡ</g> </f> <s><b>Dalmatia</b>, a part of Illyria on E. coast of the Adriatic: <r v=\"2Tim.4.10\"></r>.†</s>"},"G1166":{"l":"δείκνυμι","o":33,"ar":"<f><o>δείκνυμι</o>، <g>δεικνύω</g>، </f> <s><b>يُري، يُظهر</b>، مع المنصوب للشيء (أو للشخص) والقابل للشخص؛ </s> <s n=\"(a)\"><b>يُري، يعرض</b>: <r v=\"Matt.4.8\"></r> <r v=\"Matt.8.4\"></r>، <r v=\"Mark.1.44\"></r> <r v=\"Mark.14.15\"></r>، <r v=\"Luke.4.5\"></r> <r v=\"Luke.5.14\"></r> <r v=\"Luke.20.24\"></r> <r v=\"Luke.22.12\"></r> <r v=\"Luke.24.40\"></r>، <r v=\"John.2.18\"></r> <r v=\"John.5.20\"></r> <r v=\"John.10.32\"></r> <r v=\"John.20.20\"></r>، <r v=\"Acts.7.3\"></r> <i>(السبعينية)</i>، <r v=\"1Tim.6.15\"></r>، <r v=\"Rev.17.1\"></r> <r v=\"Rev.21.9\"></r>، <r v=\"Rev.21.10\"></r> <r v=\"Rev.22.1\"></r>، <r v=\"Rev.22.8\"></r>، المبني للمجهول، <r v=\"Heb.8.5\"></r> <i>(السبعينية)</i>؛ </s> <s n=\"(b)\"><b>يُعلن، يُعرّف</b>: <r v=\"Matt.16.21\"></r>، <r v=\"John.14.8-John.14.9\"></r>، <r v=\"Acts.10.28\"></r>، <r v=\"1Cor.12.31\"></r>، <r v=\"Rev.1.1\"></r> <r v=\"Rev.4.1\"></r> <r v=\"Rev.22.6\"></r>؛ </s> <s n=\"(c)\"><b>يُثبت، يبرهن</b>: <r v=\"Jas.2.18\"></r> <r v=\"Jas.3.13\"></r>.†</s>","en":"<f><o>δείκνυμι</o>, <g>δεικνύω</g> (v. Bl., § 23, 1; Veitch, s.v.), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7200\">רָאָה</h> hi. ;] </e> </et> <s><b>to show</b>, c. acc rei (pers.), dat. pers.; </s> <s n=\"(a)\"><b>to show, exhibit</b>: <r v=\"Matt.4.8\"></r> <r v=\"Matt.8.4\"></r>, <r v=\"Mark.1.44\"></r> <r v=\"Mark.14.15\"></r>, <r v=\"Luke.4.5\"></r> <r v=\"Luke.5.14\"></r> <r v=\"Luke.20.24\"></r> <r v=\"Luke.22.12\"></r> <r v=\"Luke.24.40\"></r>, <r v=\"John.2.18\"></r> <r v=\"John.5.20\"></r> <r v=\"John.10.32\"></r> <r v=\"John.20.20\"></r>, <r v=\"Acts.7.3\"></r> <i>(LXX)</i>, <r v=\"1Tim.6.15\"></r>, <r v=\"Rev.17.1\"></r> <r v=\"Rev.21.9\"></r>, <r v=\"Rev.21.10\"></r> <r v=\"Rev.22.1\"></r>, <r v=\"Rev.22.8\"></r>, pass., <r v=\"Heb.8.5\"></r> <i>(LXX)</i>; </s> <s n=\"(b)\"><b>to make known</b>: <r v=\"Matt.16.21\"></r>, <r v=\"John.14.8-John.14.9\"></r>, <r v=\"Acts.10.28\"></r>, <r v=\"1Cor.12.31\"></r>, <r v=\"Rev.1.1\"></r> <r v=\"Rev.4.1\"></r> <r v=\"Rev.22.6\"></r>; </s> <s n=\"(c)\"><b>to prove</b>: <r v=\"Jas.2.18\"></r> <r v=\"Jas.3.13\"></r>.†</s>"},"G1122":{"l":"γραμματεύς","o":63,"ar":"<f><o>γραμματεύς</o>، <g>-έως</g> (المنصوب الجمع <g>-εῖς</g>)، <g>ὁ</g> </f> <s> <s n=\"1.\"><b>كاتب</b>؛ <g>γ. τ. πόλεως</g>، كاتب المدينة (موظف رسمي): <r v=\"Acts.19.35\"></r>. </s> <s n=\"2.\">خارج الكتاب المقدس: عن ضابط عسكري. وكذلك في السبعينية، <r v=\"Judg.5.14\"></r>، <r v=\"2Kgs.25.19\"></r> (<h n=\"H5608\">ספר</h>)، وفي مواضع أخرى. </s> <s n=\"3.\"><b>كاتب، عالم بالكتب المقدسة، معلّم للناموس</b> (وبهذا المعنى أولاً في <r v=\"1Esd.8.3\"></r>، <r v=\"2Esd.7.6\"></r>؛ ويقابله في <r v=\"Luke.5.17\"></r> <g>νομοδιδάσκαλος</g>، وفي <r v=\"Luke.10.25\"></r> <g>νομικός</g>): <r v=\"Matt.7.29\"></r>، <r v=\"Mark.1.22\"></r>، وكثيرًا في الأناجيل: <g>γ. καὶ ἀρχιερεῖς</g>، <r v=\"Matt.2.4\"></r>، وفي مواضع أخرى؛ <g>γ. κ. Φαρισαῖοι</g>، <r v=\"Matt.5.20\"></r>، وفي مواضع أخرى؛ <g>γ. μαθητευθεὶς τῇ βασιλείᾳ τ. οὐρ.</g>، <r v=\"Matt.13.52\"></r>؛ <g>ποῦ σοφός</g>؛ <g>ποῦ γ.</g>، <r v=\"1Cor.1.20\"></r>.</s> </s>","en":"<f><o>γραμματεύς</o>, <g>-έως</g> (acc. pl., <g>-εῖς</g>, v. Bl., §8, 2), <g>ὁ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γράμμα</g>), </e> <e t=\"septuagint\">[in LXX always for <h n=\"H7860\">שׁטר</h> in Hex., elsewhere chiefly for <h n=\"H5608\">ספר</h>;]</e> </et> <s> <s n=\"1.\"><b>a secretary</b>; <g>γ. τ. πόλεως</g>, a state-clerk: <r v=\"Acts.19.35\"></r>. </s> <s n=\"2.\">In <g>π.</g>, of a military officer (Deiss., <i>BS</i>, 110f.). So <r v=\"Judg.5.14\"></r>, <r v=\"2Kgs.25.19\"></r> (<h n=\"H5608\">ספר</h>), al. </s> <s n=\"3.\"><b>a scribe, a biblical scholar, teacher of the law</b> (so first in <r v=\"1Esd.8.3\"></r>, <r v=\"2Esd.7.6\"></r>; in <r v=\"Luke.5.17\"></r>, <g>νομοδιδάσκαλος</g>; in <r v=\"Luke.10.25\"></r>, <g>νομικός</g>): <r v=\"Matt.7.29\"></r>, <r v=\"Mark.1.22\"></r>, and freq. in Gosp. <g>γ. καὶ ἀρχιερεῖς</g>, <r v=\"Matt.2.4\"></r>, et al.; <g>γ. κ. Φαρισαῖοι</g>, <r v=\"Matt.5.20\"></r>, et al.; <g>γ. μαθητευθεὶς τῇ βασιλείᾳ τ. οὐρ.</g>, <r v=\"Matt.13.52\"></r>; <g>ποῦ σοφός</g>; <g>ποῦ γ.</g>, <r v=\"1Cor.1.20\"></r> (Cremer, 167; <i>DB</i>, iv, 420, 800).</s> </s>"},"G1123":{"l":"γραπτός","o":1,"ar":"<f><o>γραπτός</o>، <g>-ή, -όν</g> </f> <s> <s n=\"1.\"><b>مرسوم، ملوَّن</b>. </s> <s n=\"2.\"><b>مكتوب</b>: <r v=\"Rom.2.15\"></r>.†</s> </s>","en":"<f><o>γραπτός</o>, <g>-ή, -όν</g> </f> <et> <e t=\"derivation\">(&lt; <g>γράφω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H4385\">מִכְתָּב</h> ;]</e> </et> <s> <s n=\"1.\"><b>painted</b>. </s> <s n=\"2.\"><b>written</b>: <r v=\"Rom.2.15\"></r>.†</s> </s>"},"G1110":{"l":"γνωστός","o":15,"ar":"<f><o>γνωστός</o>، <g>-ή, -όν</g>، صيغة متأخرة من <g>γνωστός</g> </f> <s><b>معروف</b>: <r v=\"Acts.9.42\"></r>؛ مع القابل: <r v=\"John.18.15\"></r>، <r v=\"John.18.16\"></r>، <r v=\"Acts.1.19\"></r>، <r v=\"Acts.2.14\"></r>، <r v=\"Acts.4.10\"></r>، <r v=\"Acts.13.38\"></r>، <r v=\"Acts.15.18\"></r>، <r v=\"Acts.19.17\"></r>، <r v=\"Acts.28.22\"></r>، <r v=\"Acts.28.28\"></r>؛ <g>γ. σημεῖον</g>: <i>آية ظاهرة</i> (معلومة)، أي آية صارت موضوع معرفة: <r v=\"Acts.4.16\"></r>؛ <g>γνωστὸν</g>: <r v=\"Acts.15.17\"></r>، <r v=\"Acts.15.17\"></r>؛ <g>τὸ γνωστὸν θεοῦ</g>: <r v=\"Rom.1.19\"></r>؛ في الجمع، اسمًا، <g>γνωστοί</g>: <i>المعارف</i>: <r v=\"Luke.2.44\"></r>، <r v=\"Luke.23.49\"></r>؛ وكذلك في المفرد: <r v=\"John.18.16\"></r>.†</s>","en":"<f><o>γνωστός</o>, <g>-ή, -όν</g>, later form of <g>γνωστός</g> </f> <et> <e t=\"derivation\">(&lt; <g>γιγνώσκω</g>), </e> <e t=\"septuagint\">[in LXX for various parts of <h n=\"H3045\">ידע</h> ;]</e> </et> <s><b>known</b>: <r v=\"Acts.9.42\"></r>; c. dat., <r v=\"John.18.15\"></r>, <r v=\"John.18.16\"></r> (Rec.), <r v=\"Acts.1.19\"></r> <r v=\"Acts.2.14\"></r> <r v=\"Acts.4.10\"></r> <r v=\"Acts.13.38\"></r> <r v=\"Acts.15.18\"></r> <r v=\"Acts.19.17\"></r> <r v=\"Acts.28.22\"></r>, <r v=\"Acts.28.28\"></r>; <g>γ. σημεῖον</g>, <i>a notable</i> (EV) <i>sign</i>, one that is matter of knowledge, <r v=\"Acts.4.16\"></r>; <g>γνωστὸν</g>, <r v=\"Acts.15.17\"></r>, <r v=\"Acts.15.17\"></r>; <g>τὸ γνωστὸν θεοῦ</g>, <r v=\"Rom.1.19\"></r>; in pl., as subst., <g>γνωστοί</g>, <i>acquaintances</i>, <r v=\"Luke.2.44\"></r> <r v=\"Luke.23.49\"></r>; so in sing., <r v=\"John.18.16\"></r> (WH).†</s>"},"G1116":{"l":"Γόμορρα","o":4,"ar":"<f><o>Γόμορρα</o>، <g>-ας, ἡ</g>، و<g>-ων, τά</g> (العبرية <h n=\"H6017\">עֲמֹרָה</h>)، </f> <s><b>عمورة</b>، إحدى مدن الدائرة (<r v=\"Gen.19\"></r>): <r v=\"Matt.10.15\"></r>، <r v=\"Rom.9.29\"></r> <i>(السبعينية)</i>، <r v=\"2Pet.2.6\"></r>، <r v=\"Jude.1.7\"></r>.†</s>","en":"<f><o>Γόμορρα</o>, <g>-ας, ἡ</g>, and <g>-ων, τά</g> (Heb. <h n=\"H6017\">עֲמֹרָה</h>), </f> <s><b>Gomorrah</b>, one of the cities of the plain (<r v=\"Gen.19\"></r>): <r v=\"Matt.10.15\"></r>, <r v=\"Rom.9.29\"></r> <i>(LXX)</i>, <r v=\"2Pet.2.6\"></r>, <r v=\"Jude.1.7\"></r>.†</s>"},"G1172":{"l":"δειπνέω","o":4,"ar":"<f><o>δειπνέω</o>، <g>-ῶ</g> </f> <s>تناول الوجبة الرئيسية في اليوم: <b>تغدّى، تعشّى</b>: <r v=\"Luke.17.8\"></r>، <r v=\"Luke.22.20\"></r>، <r v=\"1Cor.11.25\"></r>؛ مجازيًا: <r v=\"Rev.3.20\"></r>.†</s>","en":"<f><o>δειπνέω</o>, <g>-ῶ</g> </f> <et> <e t=\"derivation\">(&lt; <g>δεῖπνον</g>, q.v.), </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.23.1\"></r> (<h n=\"H3898\">לחם</h>), <r v=\"Tob.7.8\"></r> <r v=\"Tob.8.1\"></r>, <r v=\"Dan.11.27\"></r> * ;] </e> </et> <s>to take the chief meal of the day, <b>to dine, to sup</b>: <r v=\"Luke.17.8\"></r> <r v=\"Luke.22.20\"></r> (WH, br., R, mg. omits), <r v=\"1Cor.11.25\"></r>; metaph., <r v=\"Rev.3.20\"></r>.†</s>"},"G1112":{"l":"γογγυσμός","o":4,"ar":"<f>† <o>γογγυσμός</o>، <g>-οῦ, ὁ</g>، </f> <s><b>تذمّر، همهمة</b>: <r v=\"John.7.12\"></r>، <r v=\"Acts.6.1\"></r>؛ <g>ἄνευ γ.</g>: <r v=\"1Pet.4.9\"></r>؛ في الجمع، <g>χωρὶς γ.</g>: <r v=\"Phil.2.14\"></r>.†</s>","en":"<f>† <o>γογγυσμός</o>, <g>-οῦ, ὁ</g>, </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.58.9\"></r> (<h n=\"H205\">אָוֶן</h>), <r v=\"Exod.16.7-Exod.16.9\"></r>, <r v=\"Num.17.5\"></r>, <r v=\"Num.17.10\"></r> (<h n=\"H8519\">תְּלוּנָה</h>), <r v=\"Wis.1.10\"></r>, <r v=\"Wis.1.11\"></r> <r v=\"Sir.46.7\"></r> * ;]</e> </et> <s><b>a murmuring, muttering</b>: <r v=\"John.7.12\"></r>, <r v=\"Acts.6.1\"></r>; <g>ἄνευ γ.</g>, <r v=\"1Pet.4.9\"></r>; pl., <g>χωρὶς γ.</g>, <r v=\"Phil.2.14\"></r>.†</s>"},"G1153":{"l":"Δαμασκηνός","o":1,"ar":"<f><o>Δαμασκηνός</o>، <g>-ή, -όν </g></f> <s><b>دمشقي، من دمشق</b>: <r v=\"2Cor.11.32\"></r>.† </s>","en":"<f><o>Δαμασκηνός</o>, <g>-ή, -όν </g></f> <s><b>of Damascus, Damascene</b>: <r v=\"2Cor.11.32\"></r>.† </s>"},"G1180":{"l":"δεκατέσσαρες","o":5,"ar":"<f>† <o>δεκατέσσαρες</o>، <g>-ων, oἱ, αἱ, -α, τά</g>، </f> <s>= <g>τεσσαρεσκαίδεκα</g> في الكلاسيكية، وهي أكثر شيوعًا في اليونانية المتأخرة من الصيغة القديمة: <b>أربعة عشر</b>: <r v=\"Matt.1.17\"></r>، <r v=\"2Cor.12.2\"></r>، <r v=\"Gal.2.1\"></r> (قارن <g>τεσσαρεσκαιδέκατος</g>).†</s>","en":"<f>† <o>δεκατέσσαρες</o>, <g>-ων, oἱ, αἱ, -α, τά</g>, </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.31.41\"></r>, <r v=\"Tob.8.19\"></r>, al. ;] </e> </et> <s>= cl. <g>τεσσαρεσκαίδεκα</g>, more freq. in later Gk. than the older form and in MGr. (for thirteen and upwards) universal, <b>fourteen</b>: <r v=\"Matt.1.17\"></r>, <r v=\"2Cor.12.2\"></r>, <r v=\"Gal.2.1\"></r> (cf. <g>τεσσαρεσκαιδέκατος</g>).†</s>"},"G1178":{"l":"δεκαπέντε","o":3,"ar":"<f>† <o>δεκα-πέντε </o></f> <s>صيغة متأخرة من <g>πεντεκαίδεκα</g>، <b>خمسة عشر</b>: <r v=\"John.11.18\"></r>، <r v=\"Acts.27.5\"></r>، <r v=\"Acts.27.28\"></r>، <r v=\"Gal.1.18\"></r>.†</s>","en":"<f>† <o>δεκα-πέντε </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.27.15\"></r>, <r v=\"1Macc.10.40\"></r>, al. ;] </e> </et> <s>late form of <g>πεντεκαίδεκα</g>, <b>fifteen</b>: <r v=\"John.11.18\"></r>, <r v=\"Acts.27.5\"></r>, WH, mg., <r v=\"Acts.27.28\"></r>, <r v=\"Gal.1.18\"></r>.†</s>"},"G1143":{"l":"δάκνω","o":1,"ar":"<f><o>δάκνω </o></f> <s><b>نهش، عضّ</b>: مجازيًا، <r v=\"Gal.5.15\"></r>.†</s>","en":"<f><o>δάκνω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5391\">נשׁךְ</h>, <r v=\"Gen.49.17\"></r>, al., exc. <r v=\"Deut.8.15\"></r> (<h n=\"H8313\">שׂרף</h>) ;]</e> </et> <s><b>to bite</b>: metaph., <r v=\"Gal.5.15\"></r>.†</s>"},"G1161":{"l":"δέ","o":2797,"ar":"<f><o>δέ</o> (وقبل حروف العلة <g>δ’</g>)، </f> أداة ربط تأتي بعد أول الكلام؛ <s> <s n=\"1.\">للعطف: <b>لكن، ثم، و، فـ</b>: <r v=\"Matt.1.2\"></r> وما يليه، <r v=\"2Cor.6.15\"></r>، <r v=\"2Cor.6.16\"></r>، <r v=\"2Pet.1.5-2Pet.1.7\"></r>؛ في التكرار للتوكيد: <r v=\"Rom.3.21\"></r>، <r v=\"Rom.3.22\"></r>، <r v=\"Rom.9.30\"></r>، <r v=\"1Cor.2.6\"></r>، <r v=\"Gal.2.2\"></r>، <r v=\"Phil.2.8\"></r>؛ وفي الانتقال إلى أمر جديد: <r v=\"Matt.1.18\"></r> <r v=\"Matt.2.19\"></r>، <r v=\"Luke.13.1\"></r>، <r v=\"John.7.14\"></r>، <r v=\"Acts.6.1\"></r>، <r v=\"Rom.8.28\"></r>، <r v=\"1Cor.7.1\"></r> <r v=\"1Cor.8.1\"></r>، وفي مواضع أخرى؛ وفي الاعتراض أو الإضافة التفسيرية: <r v=\"John.3.19\"></r>، <r v=\"Rom.5.8\"></r>، <r v=\"1Cor.1.12\"></r>، <r v=\"Eph.2.4\"></r> <r v=\"Eph.5.32\"></r>، وفي مواضع أخرى؛ <g>ὡς δέ</g>: <r v=\"John.2.9\"></r>؛ <g>καὶ . . . δέ</g>: ولكن أيضًا، <r v=\"Matt.10.18\"></r>، <r v=\"Luke.1.76\"></r>، <r v=\"John.6.51\"></r>، <r v=\"Rom.11.23\"></r>، وفي مواضع أخرى؛ <g>καὶ ἐὰν δέ</g>: <b>بل وإن</b>، <r v=\"John.8.16\"></r>. </s> <s n=\"2.\">للاستدراك: <b>لكن، ومن جهة أخرى</b>، وأصلاً جوابًا لـ <g>μέν</g> سابقة (انظره)، وتميِّز كلمة أو جملة عمّا قبلها (وفي العهد الجديد غالبًا بدون <g>μέν</g>): <g>ἐὰν δέ</g>، <r v=\"Matt.6.14\"></r>، <r v=\"Matt.6.23\"></r>، وفي مواضع أخرى؛ <g>ἐγὼ</g> (<g>σὺ</g>، إلخ) <g>δέ</g>، <r v=\"Matt.5.22\"></r> <r v=\"Matt.6.6\"></r>، <r v=\"Mark.8.29\"></r>، وفي مواضع أخرى؛ <g>ὁ δέ, αὐτὸς δέ</g>، <r v=\"Mark.1.45\"></r>، <r v=\"Luke.4.40\"></r>، وفي مواضع أخرى؛ وبعد النفي: <r v=\"Matt.6.19\"></r>، <r v=\"Matt.6.20\"></r>، <r v=\"Rom.3.4\"></r>، <r v=\"1Thess.5.21\"></r>، وفي مواضع أخرى.</s> </s>","en":"<f><o>δέ</o> (before vowels <g>δ’</g>; on the general neglect of the elision in NT, v. WH, <i>App.</i>, 146; Tdf., <i>Pr.</i>, 96), </f> post-positive conjunctive particle; <s> <s n=\"1.\">copulative, <b>but, in the next place, and, now</b> (Abbott, <i>JG</i>, 104): <r v=\"Matt.1.2\"></r>ff., <r v=\"2Cor.6.15\"></r>, <r v=\"2Cor.6.16\"></r>, <r v=\"2Pet.1.5-2Pet.1.7\"></r>; in repetition for emphasis, <r v=\"Rom.3.21\"></r>, <r v=\"Rom.3.22\"></r>, <r v=\"Rom.9.30\"></r>, <r v=\"1Cor.2.6\"></r>, <r v=\"Gal.2.2\"></r>, <r v=\"Phil.2.8\"></r>; in transition to something new, <r v=\"Matt.1.18\"></r> <r v=\"Matt.2.19\"></r>, <r v=\"Luke.13.1\"></r>, <r v=\"John.7.14\"></r>, <r v=\"Acts.6.1\"></r>, <r v=\"Rom.8.28\"></r>, <r v=\"1Cor.7.1\"></r> <r v=\"1Cor.8.1\"></r>, al.; in explanatory parenthesis or addition, <r v=\"John.3.19\"></r>, <r v=\"Rom.5.8\"></r>, <r v=\"1Cor.1.12\"></r>, <r v=\"Eph.2.4\"></r> <r v=\"Eph.5.32\"></r>, al.; <g>ὡς δέ</g>, <r v=\"John.2.9\"></r>; <g>καὶ . . . δέ</g>, but also, <r v=\"Matt.10.18\"></r>, <r v=\"Luke.1.76\"></r>, <r v=\"John.6.51\"></r>, <r v=\"Rom.11.23\"></r>, al.; <g>καὶ ἐὰν δέ</g>, <b>yea even if</b>, <r v=\"John.8.16\"></r>. </s> <s n=\"2.\">Adversative, <b>but, on the other hand</b>, prop., answering to a foregoing <g>μέν</g> (q.v.), and distinguishing a word or clause from one preceding (in NT most freq. without <g>μέν</g>; Bl., §77, 12): <g>ἐὰν δέ</g>, <r v=\"Matt.6.14\"></r>, <r v=\"Matt.6.23\"></r>, al.; <g>ἐγὼ</g> (<g>σὺ</g>, etc.) <g>δέ</g>, <r v=\"Matt.5.22\"></r> <r v=\"Matt.6.6\"></r>, <r v=\"Mark.8.29\"></r>, al.; <g>ὁ δέ, αὐτὸς δέ</g>, <r v=\"Mark.1.45\"></r>, <r v=\"Luke.4.40\"></r>, al.; after a negation, <r v=\"Matt.6.19\"></r>, <r v=\"Matt.6.20\"></r>, <r v=\"Rom.3.4\"></r>, <r v=\"1Thess.5.21\"></r>, al.</s> </s>"},"G1104":{"l":"γνησίως","o":1,"ar":"<f>** <o>γνησίως</o>، ظرف، </f> <s><b>بإخلاص، بأمانة</b>: فيلبي 2: 20.†</s>","en":"<f>** <o>γνησίως</o>, adv., </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.14.8\"></r>, <r v=\"3Macc.3.23\"></r> * ;]</e> </et> <s><b>sincerely, honourably</b>: Phi 2:20 (for a parallel in <g>π.</g>, v. MM, s.v.).†</s>"},"G1121":{"l":"γράμμα","o":14,"ar":"<f><o>γράμμα</o>، <g>-τος, τό</g> </f> <s> <s n=\"1.\"><b>ما يُخَطّ</b> أو <b>يُرسَم، صورة</b>. </s> <s n=\"2.\"><b>ما يُكتب</b>؛ <s n=\"(1)\"><b>حرف (من حروف الكتابة)</b>: <r v=\"Gal.6.11\"></r>؛ </s> <s n=\"(2)\"><b>كتابة، وثيقة مكتوبة</b>؛ <s n=\"(a)\"><b>صكّ</b> أو <b>حساب</b>: <r v=\"Luke.16.6\"></r>، <r v=\"Luke.16.7\"></r>؛ </s> <s n=\"(b)\"><b>رسالة</b>: <r v=\"Acts.28.21\"></r>؛ </s> <s n=\"(c)\"><g>τὰ ἱερὰ γ.</g>، <i>الكتب المقدسة</i>، أي العهد القديم: <r v=\"2Tim.3.15\"></r>؛ </s> <s n=\"(d)\"><g>τὸ γ.</g>، <i>الحرف</i>، أي الكلمة المكتوبة بوصفها سلطة خارجية، في مقابل عمل الروح المباشر كما ظهر في العهد الجديد: <r v=\"Rom.2.27\"></r>، <r v=\"Rom.2.29\"></r>، <r v=\"Rom.7.6\"></r>، <r v=\"2Cor.3.6\"></r>، <r v=\"2Cor.3.7\"></r>؛ </s> </s> <s n=\"(3)\"><g>τὰ γ.</g>، <i>الكتب</i>، أي <i>العلم</i>: <r v=\"John.7.15\"></r>، <r v=\"Acts.26.24\"></r>.</s> †</s> </s>","en":"<f><o>γράμμα</o>, <g>-τος, τό</g> </f> <et> <e t=\"derivation\">(&lt; <g>γράφω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H5612\">סֵפֶר</h>, etc. ;]</e> </et> <s> <s n=\"1.\"><b>that which is traced</b> or <b>drawn, a picture</b>. </s> <s n=\"2.\"><b>that which is written</b>; <s n=\"(1)\"><b>a character, letter</b>: <r v=\"Gal.6.11\"></r>; </s> <s n=\"(2)\"><b>a writing, a written document</b>; <s n=\"(a)\"><b>a bill</b> or <b>account</b>: <r v=\"Luke.16.6\"></r>, <r v=\"Luke.16.7\"></r>; </s> <s n=\"(b)\"><b>a letter</b>: <r v=\"Acts.28.21\"></r>; </s> <s n=\"(c)\"><g>τὰ ἱερὰ γ.</g>, <i>the sacred writings</i>, i.e. the OT: <r v=\"2Tim.3.15\"></r> (so in Philo, <i>Vit. Mos.</i>, iii, 39) ; </s> <s n=\"(d)\"><g>τὸ γ.</g>, <i>the letter</i>, the written word as an external authority in contrast with the direct influence of the Spirit as manifested in the new Covenant: <r v=\"Rom.2.27\"></r>, <r v=\"Rom.2.29\"></r> <r v=\"Rom.7.6\"></r>, <r v=\"2Cor.3.6\"></r>, <r v=\"2Cor.3.7\"></r>; </s> </s> <s n=\"(3)\"><g>τὰ γ.</g>, <i>letters</i>, i.e. <i>learning</i>: <r v=\"John.7.15\"></r>, <r v=\"Acts.26.24\"></r>. (In <g>π.</g> an illiterate person is very frequently referred to as <g>γράμματα μὴ εἰδότης</g>, and this \"never means anything else than inability to write\": MM, <i>Exp.</i>, x; but v. also Cremer, 166; <i>DCG</i>, i, 202; ii, 584.)</s> †</s> </s>"},"G1111":{"l":"γογγύζω","o":8,"ar":"<f>† <o>γογγύζω</o>، </f> <s><b>يدمدم، يتذمّر</b>: <r v=\"1Cor.10.10\"></r>؛ يليه <g>κατά</g>، <r v=\"Matt.20.11\"></r>؛ <g>πρός</g>، <r v=\"Luke.5.30\"></r>؛ <g>περί</g>، <r v=\"John.6.41\"></r>، <r v=\"Acts.6.61\"></r>؛ <g>μετ’ ἀλλήλων</g>، <r v=\"John.6.43\"></r>؛ مع المنصوب، يليه <g>περί</g>، <r v=\"John.7.32\"></r> (قارن <g>δια-γογγύζω</g>).†</s>","en":"<f>† <o>γογγύζω</o>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3885\">לוּן</h> ;]</e> </et> <s><b>to mutter, murmur</b>: <r v=\"1Cor.10.10\"></r>; seq. <g>κατά</g>, <r v=\"Matt.20.11\"></r>; <g>πρός</g>, <r v=\"Luke.5.30\"></r>; <g>περί</g>, <r v=\"John.6.41\"></r>, <r v=\"Acts.6.61\"></r>; <g>μετ’ ἀλλήλων</g>, <r v=\"John.6.43\"></r>; c. acc., seq. <g>περί</g>, <r v=\"John.7.32\"></r> (cf. <g>δια-γογγύζω</g>).†</s>"},"G1128":{"l":"γυμνάζω","o":4,"ar":"<f>** <o>γυμνάζω</o> </f> <s> <s n=\"1.\">أصلاً: <b>يتدرّب عاريًا</b>. </s> <s n=\"2.\">عمومًا: <b>يروّض، يدرّب</b> الجسد أو العقل: <r v=\"1Tim.4.7\"></r>، <r v=\"Heb.5.14\"></r> <r v=\"Heb.12.11\"></r>، <r v=\"2Pet.2.14\"></r>.†</s></s>","en":"<f>** <o>γυμνάζω</o> </f> <et> <e t=\"derivation\">(&lt; <g>γυμνός</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.10.15\"></r> * ;]</e> </et> <s> <s n=\"1.\">properly, <b>to exercise naked</b>. </s> <s n=\"2.\">Generally, <b>to exercise, train</b> the body or mind: <r v=\"1Tim.4.7\"></r>, <r v=\"Heb.5.14\"></r> <r v=\"Heb.12.11\"></r>, <r v=\"2Pet.2.14\"></r>.†</s></s>"},"G1131":{"l":"γυμνός","o":15,"ar":"<f><o>γυμνός</o>، <g>-ή, -όν</g>، </f> <s><b>عريان، بلا ثياب</b>، وأحيانًا <b>قليل الثياب</b> أو <b>رثّ الثياب</b> (<r v=\"Isa.20.2\"></r> وما يليه، <r v=\"Tob.1.16\"></r>، <r v=\"2Macc.11.12\"></r>): <r v=\"Matt.25.36\"></r>، <r v=\"Matt.25.38\"></r> <r v=\"Matt.25.43\"></r>، <r v=\"Matt.25.44\"></r>، <r v=\"Mark.14.52\"></r>، <r v=\"John.21.7\"></r>، <r v=\"Acts.19.16\"></r>، <r v=\"Jas.2.15\"></r>، <r v=\"Rev.3.17\"></r> <r v=\"Rev.16.15\"></r>، <r v=\"Rev.17.16\"></r>؛ اسمًا، <g>γ.</g>: <b>الجسد العاري</b>، <r v=\"Mark.14.51\"></r>. مجازيًا، عن الأشياء المكشوفة، <r v=\"Heb.4.13\"></r>؛ عن النفس بلا جسد، <r v=\"2Cor.5.3\"></r>؛ عن البذرة: <b>مجرّدة</b>، <r v=\"1Cor.15.37\"></r>.†</s>","en":"<f><o>γυμνός</o>, <g>-ή, -όν</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6174\">עָרוֹם</h> ;]</e> </et> <s><b>naked, without clothing</b>, and sometimes (as freq. in cl.) <b>scantily</b> or <b>poorly clad</b> (<r v=\"Isa.20.2\"></r>ff., <r v=\"Tob.1.16\"></r>, <r v=\"2Macc.11.12\"></r>): <r v=\"Matt.25.36\"></r>, <r v=\"Matt.25.38\"></r> <r v=\"Matt.25.43\"></r>, <r v=\"Matt.25.44\"></r>, <r v=\"Mark.14.52\"></r>, <r v=\"John.21.7\"></r>, <r v=\"Acts.19.16\"></r>, <r v=\"Jas.2.15\"></r>, <r v=\"Rev.3.17\"></r> <r v=\"Rev.16.15\"></r>, <r v=\"Rev.17.16\"></r>; as subst., to <g>γ.</g>, <b>the naked body</b>, <r v=\"Mark.14.51\"></r>. Metaph., of things exposed, <r v=\"Heb.4.13\"></r>; of the soul without a body (Plat., <i>Crat.</i>, c., 20, and cf. Deiss., <i>LAE</i>, 293), <r v=\"2Cor.5.3\"></r>; of seed, <b>bare</b>, <r v=\"1Cor.15.37\"></r> (Cremer, 168).†</s>"},"G1126":{"l":"γραώδης","o":1,"ar":"<f><o>γραώδης</o>، <g>-ες</g> (من <g>γραῦς</g>: <i>امرأة عجوز</i>، و<g>εἶδος</g>: <i>هيئة</i>)، </f> <s><b>خاص بالعجائز، خرافي</b>: <r v=\"1Tim.4.7\"></r>.†</s>","en":"<f><o>γραώδης</o>, <g>-ες</g> (<g>γραῦς</g>, <i>an old woman</i>, <g>εἶδος</g>), </f> <s><b>anile, old-womanish</b>: <r v=\"1Tim.4.7\"></r>.†</s>"},"G1132":{"l":"γυμνότης","o":3,"ar":"<f><o>γυμνότης</o>، <g>-ητος, ἡ</g> </f> <s><b>عُري</b>: <r v=\"Rom.8.35\"></r>، <r v=\"2Cor.11.27\"></r>، <r v=\"Rev.3.18\"></r>.†</s>","en":"<f><o>γυμνότης</o>, <g>-ητος, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γυμνός</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H5903\">עֵירֹם</h>, <r v=\"Deut.28.48\"></r> * ;]</e> </et> <s><b>nakedness</b>: <r v=\"Rom.8.35\"></r>, <r v=\"2Cor.11.27\"></r>, <r v=\"Rev.3.18\"></r>.†</s>"},"G1186":{"l":"δένδρον","o":25,"ar":"<f><o>δένδρον</o>، <g>-ου, τό</g></f> <s><b>شجرة</b>: <r v=\"Matt.3.10\"></r>، وفي مواضع أخرى؛ <g>δ. ἀγαθόν</g>، <r v=\"Matt.7.17-Matt.7.18\"></r>؛ <g>δ. καλόν</g>، <r v=\"Matt.12.33\"></r>، <r v=\"Luke.6.43\"></r>؛ <g>δ. σαπρόν</g>، <r v=\"Matt.7.17\"></r>، <r v=\"Matt.7.18\"></r> <r v=\"Matt.12.33\"></r>، <r v=\"Luke.6.43\"></r>؛ <g>γίνεσθαι δ.</g>، <r v=\"Matt.13.32\"></r>؛ <g>γ. εἰς δ.</g>، <r v=\"Luke.13.19\"></r>.</s>","en":"<f><o>δένδρον</o>, <g>-ου, τό</g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6086\">עֵץ</h>, etc. ;] </e> </et> <s><b>a tree</b>: <r v=\"Matt.3.10\"></r>, al.; <g>δ. ἀγαθόν</g>, <r v=\"Matt.7.17-Matt.7.18\"></r>; <g>δ. καλόν</g>, <r v=\"Matt.12.33\"></r>, <r v=\"Luke.6.43\"></r>; <g>δ. σαπρόν</g>, <r v=\"Matt.7.17\"></r>, <r v=\"Matt.7.18\"></r> <r v=\"Matt.12.33\"></r>, <r v=\"Luke.6.43\"></r>; <g>γίνεσθαι δ.</g>, <r v=\"Matt.13.32\"></r>; <g>γ. εἰς δ.</g>, <r v=\"Luke.13.19\"></r>.</s>"},"G1181":{"l":"δεκάτη","o":4,"ar":"<f><o>δεκάτη</o>، <g>-ης, ἡ </g>، وهي أصلاً مؤنث (بتقدير <g>μέρος</g>) من <g>δέκατος, -η, -ον</g>، </f> <s><b>جزء من عشرة، عُشر</b>: <r v=\"Heb.7.2\"></r>، <r v=\"Heb.7.4\"></r>، <r v=\"Heb.7.8\"></r>، <r v=\"Heb.7.9\"></r>.†</s>","en":"<f><o>δεκάτη</o>, <g>-ης, ἡ </g> prop. fem. (sc. <g>μέρος</g>) of <g>δέκατος, -η, -ον</g>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H4643\">מַעֲשֵׂר</h>: <r v=\"Gen.14.20\"></r>, <r v=\"Neh.12.44\"></r>, et al. ;] </e> </et> <s><b>a tenth part, a tithe</b>: <r v=\"Heb.7.2\"></r>, <r v=\"Heb.7.4\"></r>, <r v=\"Heb.7.8\"></r>, <r v=\"Heb.7.9\"></r> (for a curious inversion of the Biblical use, v. MM, s.v.).†</s>"},"G1182":{"l":"δέκατος","o":3,"ar":"<f><o>δέκατος</o>، <g>-η, -ον</g> </f> <s><b>العاشر</b>: <r v=\"John.1.40\"></r>، <r v=\"Acts.19.9\"></r>، <r v=\"Rev.11.13\"></r>؛ <r v=\"Rev.21.20\"></r>.†</s>","en":"<f><o>δέκατος</o>, <g>-η, -ον</g> </f> <et> <e t=\"derivation\">(&lt; <g>δέκα</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H4643\">מַעֲשֵׂר</h> and cognate forms ;] </e> </et> <s><b>tenth</b>: <r v=\"John.1.40\"></r>, <r v=\"Acts.19.9\"></r> (WH, txt., RV omit), <r v=\"Rev.11.13\"></r>; <r v=\"Rev.21.20\"></r>.†</s>"},"G1134":{"l":"γυναικεῖος","o":1,"ar":"<f><o>γυναικεῖος</o>، <g>-α, -ον</g> </f> <s><b>نسائي، أنثوي</b>: <r v=\"1Pet.3.7\"></r>.†</s>","en":"<f><o>γυναικεῖος</o>, <g>-α, -ον</g> </f> <et> <e t=\"derivation\">(&lt; <g>γυνή</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H802\">אִשָּׁה</h> ;]</e> </et> <s><b>female</b>: <r v=\"1Pet.3.7\"></r>.†</s>"},"G1185":{"l":"δελεάζω","o":3,"ar":"<f>* <o>δελεάζω</o></f> <s><b>اصطاد بالطُّعم</b>؛ مجازيًا: <b>أغوى، أغرى</b>: مع المنصوب، <r v=\"2Pet.2.14\"></r>، <r v=\"2Pet.2.18\"></r>؛ المبني للمجهول، <r v=\"Jas.1.14\"></r>.†</s>","en":"<f>* <o>δελεάζω</o></f> <et> <e t=\"derivation\">(&lt; <g>δέλεαρ</g>, <b>a bait</b>), </e> </et> <s><b>to allure by a bait</b>: metaph., <b>to allure, entice</b>: c. acc, <r v=\"2Pet.2.14\"></r>, <r v=\"2Pet.2.18\"></r>; pass., <r v=\"Jas.1.14\"></r>.†</s>"},"G1183":{"l":"δεκατόω","o":2,"ar":"<f>† <o>δεκατόω</o>، <g>-ῶ, </g></f> <s><b>عشّر، أخذ العُشر من</b>: مع منصوب الشخص، <r v=\"Heb.7.6\"></r>؛ المبني للمجهول: <b>أدّى العُشر</b>: <r v=\"Heb.7.9\"></r>.†</s>","en":"<f>† <o>δεκατόω</o>, <g>-ῶ, </g></f> <et> <e t=\"derivation\">= cl. <g>-τεύω</g> (&lt; <g>δεκάτη</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Neh.10.37\"></r> (<h n=\"H6237\">עשׂר</h> pi.) * ;] </e> </et> <s><b>to take tithe of</b>: c. acc. pers., <r v=\"Heb.7.6\"></r>; pass. <b>to pay tithe</b>: <r v=\"Heb.7.9\"></r>.†</s>"},"G1164":{"l":"δεῖγμα","o":1,"ar":"<f>* <o>δεῖγμα</o>، <g>-τος, τό</g> </f> <s> <s n=\"1.\">في اليونانية الكلاسيكية: <b>شيء معروض، عيّنة</b>. </s> <s n=\"2.\">= <g>παράδ-</g> في الكلاسيكية (قارن <g>ὑπόδ-</g>، <r v=\"2Pet.2.6\"></r>)، <b>عبرة، مثال</b> (للتحذير): <r v=\"Jude.1.7\"></r>.† </s> </s>","en":"<f>* <o>δεῖγμα</o>, <g>-τος, τό</g> </f> <et> <e t=\"derivation\">(&lt; <g>δείκνυμι</g>); </e> </et> <s> <s n=\"1.\">(cl.) <b>a thing shown, a specimen</b>. </s> <s n=\"2.\">= cl. <g>παράδ-</g> (cf. <g>ὑπόδ-</g>, <r v=\"2Pet.2.6\"></r>), <b>an example</b> (a warning): <r v=\"Jude.1.7\"></r>.† </s> </s>"},"G1169":{"l":"δειλός","o":3,"ar":"<f><o>δειλός</o>، <g>-ή, όν</g> </f> <s><b>جبان، خائف</b>: <r v=\"Matt.8.26\"></r>، <r v=\"Mark.4.40\"></r>، <r v=\"Rev.21.8\"></r>.†</s>","en":"<f><o>δειλός</o>, <g>-ή, όν</g> </f> <et> <e t=\"derivation\">(&lt; <g>δέος</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H7390\">רַךְ</h>, etc. ;] </e> </et> <s><b>cowardly, fearful</b>: <r v=\"Matt.8.26\"></r>, <r v=\"Mark.4.40\"></r>, <r v=\"Rev.21.8\"></r>.†</s>"},"G1192":{"l":"δέρμα","o":1,"ar":"<f><o>δέρμα</o>، <g>-τος, τό</g></f> <s><b>الجلد</b>، <b>إهاب</b> الحيوانات: <g>ἐν αἰγίοις δ.</g>، <r v=\"Heb.11.37\"></r>.†</s>","en":"<f><o>δέρμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>δέρω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H5785\">עוֹר</h> ;] </e> </et> <s><b>the skin, hide</b> of beasts: <g>ἐν αἰγίοις δ.</g>, <r v=\"Heb.11.37\"></r>.†</s>"},"G1137":{"l":"γωνία","o":9,"ar":"<f><o>γωνία</o>، <g>-ας, ἡ</g> </f> <s><b>زاوية، ركن</b>: <r v=\"Matt.6.5\"></r>، <r v=\"Acts.26.26\"></r>؛ <g>τ. τέσσαρας γ. τ. γῆς</g>، <r v=\"Rev.7.1\"></r>، <r v=\"Rev.20.8\"></r>؛ <g>κεφαλὴ γνωνίας</g> (ترجمةً لـ<h n=\"H7218,H6438\">רֹאשׁ פִּנָּה</h> في السبعينية، <r v=\"LXX:Ps.117.22\"></r>)، <r v=\"Matt.21.42\"></r>، <r v=\"Mark.12.10\"></r>، <r v=\"Luke.20.17\"></r>، <r v=\"Acts.4.11\"></r>، <r v=\"1Pet.2.7\"></r>.†</s>","en":"<f><o>γωνία</o>, <g>-ας, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γόνυ</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6438\">פִּנָּה</h> ;] </e> </et> <s><b>an angle, a corner</b>: <r v=\"Matt.6.5\"></r>, <r v=\"Acts.26.26\"></r>; <g>τ. τέσσαρας γ. τ. γῆς</g>, <r v=\"Rev.7.1\"></r>, <r v=\"Rev.20.8\"></r>; <g>κεφαλὴ γνωνίας</g> (<h n=\"H7218,H6438\">רֹאשׁ פִּנָּה</h>, <r v=\"LXX:Ps.117.22\"></r>, LXX), <r v=\"Matt.21.42\"></r>, <r v=\"Mark.12.10\"></r>, <r v=\"Luke.20.17\"></r>, <r v=\"Acts.4.11\"></r>, <r v=\"1Pet.2.7\"></r>.†</s>"},"G1150":{"l":"δαμάζω","o":4,"ar":"<f><o>δαμάζω </o></f> <s><b>روّض، ذلّل</b>: <r v=\"Mark.5.4\"></r>، <r v=\"Jas.3.7\"></r>؛ مجازيًا، <g>τ. γλῶσσαν</g>، <r v=\"Jas.3.8\"></r>.†</s>","en":"<f><o>δαμάζω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Dan.2.40\"></r> (<h n=\"H2827\">חֲשַׁל</h>) * ;]</e> </et> <s><b>to tame, subdue</b>: <r v=\"Mark.5.4\"></r>, <r v=\"Jas.3.7\"></r>; metaph., <g>τ. γλῶσσαν</g>, <r v=\"Jas.3.8\"></r> (Field, <i>Notes</i>, 237 f.).†</s>"},"G1117":{"l":"γόμος","o":3,"ar":"<f><o>γόμος</o>، <g>-ου, ὁ</g> </f> <s><b>وسق السفينة، شحنة</b>: <r v=\"Acts.21.3\"></r>، <r v=\"Rev.18.11\"></r>، <r v=\"Rev.18.12\"></r>.†</s>","en":"<f><o>γόμος</o>, <g>-ου, ὁ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γέμω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.23.5\"></r>, <r v=\"2Kgs.5.17\"></r> (<h n=\"H4853\">מַשָּׂא</h>) * ;]</e> </et> <s><b>a ship's freight, cargo</b>: <r v=\"Acts.21.3\"></r>, <r v=\"Rev.18.11\"></r>, <r v=\"Rev.18.12\"></r>.†</s>"},"G1142":{"l":"δαίμων","o":1,"ar":"<f><o>δαίμων</o>، <g>-ονος, ὁ, ἡ </g></f> <s>= <g>δαιμόνιον</g>؛ <b>شيطان، روح شرير</b>: <r v=\"Matt.8.31\"></r>.†</s>","en":"<f><o>δαίμων</o>, <g>-ονος, ὁ, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1408\">גַּד</h>, <r v=\"Isa.65.11\"></r> (<h>א</h>; <g>δαιμονίῳ</g>, AB) * ;] </e> </et> <s>in cl. and NT = <g>δαιμόνιον</g>; <b>a demon</b>: <r v=\"Matt.8.31\"></r>.†</s>"},"G1113":{"l":"γογγυστής","o":1,"ar":"<f>**† <o>γογγυστής</o>، <g>-οῦ, ὁ</g> (مشتقة من <g>γογγύζω</g>)؛ [في ترجمة سيماخوس: <r v=\"Prov.26.22\"></r>، <r v=\"Isa.29.24\"></r>؛ وثيودوتيون: <r v=\"Prov.26.20\"></r> *؛] </f> <s><b>متذمّر</b>: <r v=\"Jude.1.16\"></r>.†</s>","en":"<f>**† <o>γογγυστής</o>, <g>-οῦ, ὁ</g> (&lt; <g>γογγύζω</g>); [in Sm.: <r v=\"Prov.26.22\"></r>, <r v=\"Isa.29.24\"></r>; Th.: <r v=\"Prov.26.20\"></r> * ;] </f> <s><b>a murmurer</b>: <r v=\"Jude.1.16\"></r>.†</s>"},"G1141":{"l":"δαιμονιώδης","o":1,"ar":"<f>**† <o>δαιμονιώδης</o>، <g>-ες</g></f> <s><b>شيطاني</b>: <r v=\"Jas.3.15\"></r>.†</s>","en":"<f>**† <o>δαιμονιώδης</o>, <g>-ες</g></f> <et> <e t=\"derivation\">(&lt; <g>δαιμόνιον</g>, <g>εἶδος</g>), </e> <e t=\"septuagint\">[in Sm.: <r v=\"LXX:Ps.90.6\"></r> * ;]</e> </et> <s><b>demon-like</b>: <r v=\"Jas.3.15\"></r> (Cremer, 171).†</s>"},"G1105":{"l":"γνόφος","o":1,"ar":"<f><o>γνόφος</o> (صيغة متأخرة من <g>δν-</g>)، </f> <s><b>ظلام، ديجور</b> (ويتضمّن معنى العاصفة): <r v=\"Heb.12.18\"></r>.†</s>","en":"<f><o>γνόφος</o> (later form of <g>δν-</g>), </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H651\">אָפֵל</h>, <h n=\"H6205\">עֲרָפֶל</h>, etc. ;]</e> </et> <s><b>darkness, gloom</b> (including \"an element of tempest,\" Tr., <i>Syn.</i>, §c): <r v=\"Heb.12.18\"></r>.†</s> <sy><i>SYN.</i>: <g>ἀχλύς, ζόφος, σκότος</g> (Tr., l.c.; <i>DB</i>, i, 457<i>a</i>).</sy>"},"G1176":{"l":"δέκα","o":25,"ar":"<f><o>δέκα</o>، <g>οἱ, αἱ, τά</g>، </f> <s><b>عشرة</b>: <r v=\"Matt.20.24\"></r>، وفي مواضع أخرى؛ <g>θλίψις ἡμερῶν δ.</g>، أي لمدة قصيرة: <r v=\"Rev.2.10\"></r>.†</s>","en":"<f><o>δέκα</o>, <g>οἱ, αἱ, τά</g>, </f> <s><b>ten</b>: <r v=\"Matt.20.24\"></r>, al.; <g>θλίψις ἡμερῶν δ.</g>, i.e. of brief duration: <r v=\"Rev.2.10\"></r>.†</s>"},"G1136":{"l":"Γώγ","o":1,"ar":"<f><o>Γώγ</o>، <g>ὁ</g> (العبرية <h n=\"H1463\">גּוֹג</h>)، لا يُصرَّف، </f> <s><b>جوج</b>، مقرونًا بماجوج (انظره): <r v=\"Rev.20.8\"></r>.†</s>","en":"<f><o>Γώγ</o>, <g>ὁ</g> (Heb. <h n=\"H1463\">גּוֹג</h>), indecl., </f> <s><b>Gog</b>, assoc. with Magog (q.v): <r v=\"Rev.20.8\"></r>.†</s>"},"G1151":{"l":"δάμαλις","o":1,"ar":"<f><o>δάμαλις</o>، <g>-εως, ἡ</g></f> <s><b>عِجلة (بقرة صغيرة)</b>، <r v=\"Heb.9.13\"></r>.†</s>","en":"<f><o>δάμαλις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(fem. of <g>δαμάλης</g>, <i>a bullock</i>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6510\">פָּרָה</h>, <h n=\"H5697\">עֶגְלָה</h> ;] </e> </et> <s><b>a heifer</b>, <r v=\"Heb.9.13\"></r>.†</s>"},"G1115":{"l":"Γολγοθᾶ","o":2,"ar":"<f><o>Γολγοθά</o> (الآرامية <h n=\"????\">גָּלְגָּלְתָּא</h> = العبرية <h n=\"H1538\">גֻּלְגֹּלֶת</h>، وفي السبعينية <g>κρανίον</g>، <r v=\"Judg.9.53\"></r>، <r v=\"2Sam.9.35\"></r>)؛ لا يُصرَّف (ما عدا <r v=\"Mark.15.22\"></r>، <g>-άν</g>)، </f> <s><b>جلجثة</b>، موضع الصلب: <r v=\"Matt.27.33\"></r>، <r v=\"Mark.15.22\"></r>، <r v=\"John.19.17\"></r>.†</s>","en":"<f><o>Γολγοθά</o> (Rec. <g>-θᾶ</g>; WH, mg., <g>Γολγόθ</g>, Jo, l.c., Aram. <h n=\"????\">גָּלְגָּלְתָּא</h> = Heb. <h n=\"H1538\">גֻּלְגֹּלֶת</h>, LXX, <g>κρανίον</g>, <r v=\"Judg.9.53\"></r>, <r v=\"2Sam.9.35\"></r>); indecl. (exc. <r v=\"Mark.15.22\"></r>, <g>-άν</g>), </f> <s><b>Golgotha</b>, the place of the crucifixion: <r v=\"Matt.27.33\"></r>, <r v=\"Mark.15.22\"></r>, <r v=\"John.19.17\"></r>.†</s>"},"G1120":{"l":"γονυπετέω","o":4,"ar":"<f>*† <o>γονυπετέω</o>، <g>-ῶ</g> (مشتقة من <g>γόνυ, πίπτω</g>)؛ </f> <s> <s n=\"1.\"><b>جثا على ركبتيه</b>: يليه <g>ἔμπροσθεν</g>، <r v=\"Matt.27.29\"></r>. </s> <s n=\"2.\"><b>جثا أمام</b> أحد: مع المنصوب، <r v=\"Matt.17.14\"></r>، <r v=\"Mark.1.40\"></r>، <r v=\"Mark.10.17\"></r>.†</s> </s>","en":"<f>*† <o>γονυπετέω</o>, <g>-ῶ</g> (&lt; <g>γόνυ, πίπτω</g>); </f> <s> <s n=\"1.\"><b>to fall on the knees</b>: seq. <g>ἔμπροσθεν</g>, <r v=\"Matt.27.29\"></r>. </s> <s n=\"2.\"><b>to fall down before</b> one: c. acc., <r v=\"Matt.17.14\"></r>, <r v=\"Mark.1.40\"></r>, R, txt., <r v=\"Mark.10.17\"></r>.†</s> </s>"},"G1109":{"l":"γνώστης","o":1,"ar":"<f><o>γνώστης</o>، <g>-ου, ὁ</g> </f> <s><b>عارف، عالِم خبير</b>: <r v=\"Acts.26.3\"></r>.†</s>","en":"<f><o>γνώστης</o>, <g>-ου, ὁ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γιγνώσκω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3049\">יִדְּעֹנִי</h> ;]</e> </et> <s><b>one who knows, an expert</b>: <r v=\"Acts.26.3\"></r>.†</s>"},"G1174":{"l":"δεισιδαίμων","o":1,"ar":"<f>* <o>δεισι-δαίμων</o>، <g>-ον</g></f> <s><b>مُتَّقٍ للآلهة، متديّن</b>؛ صيغة التفضيل <g>-μονεστέρους</g> (الترجمة المعتمدة: <b>مفرطون في الخرافة</b>، والترجمة المنقحة في المتن: <b>ميّالون إلى الخرافة نوعًا ما</b>، وهو معنى تُستعمل فيه الكلمة أحيانًا)، <b>أكثر تديّنًا، أكثر خوفًا من الله</b> من غيرهم، <b>متديّنون جدًا</b>: <r v=\"Acts.17.22\"></r>.† </s>","en":"<f>* <o>δεισι-δαίμων</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>δείδω</g>, <b>to fear</b>; <g>δαίμων</g>, <b>deity</b>) </e> </et> <s><b>reverent to the deity, religious</b>; compar. <g>-μονεστέρους</g> (AV, <b>too superstitious</b>, R, txt., <b>somewhat superstitious</b>, a sense in wh. the word is sometimes used; cf. Field, <i>Notes</i>, 125), <b>more religious, God fearing</b>, than others, <b>quite religious</b> (Abbott, <i>Essays</i>, 105 ff.; Deiss., <i>LAE</i>, 285): <r v=\"Acts.17.22\"></r>.† </s> <sy><i>SYN.</i>: <g>εὐσεβής</g> (q.v.), <g>θεοσεβής</g>, <g>θρῆσκος</g> (Cremer, 681; <i>DB</i>, <i>ext.</i>, 142 <i>a</i>). </sy>"},"G1101":{"l":"γλωσσόκομον","o":2,"ar":"<f>† <o>γλωσσόκομον</o>، <g>-ου, τό</g>، صيغة دارجة للكلاسيكية <g>γλωσσοκομεῖον</g> </f> <s> <s n=\"1.\">في اليونانية الكلاسيكية (= <g>-εῖον</g>): <b>علبة</b> لحفظ قصبات الآلات الموسيقية أو ألسنتها. </s> <s n=\"2.\">كما في السبعينية: <b>صندوق</b>: <r v=\"John.12.6\"></r> <r v=\"John.13.29\"></r>.†</s> </s>","en":"<f>† <o>γλωσσόκομον</o>, <g>-ου, τό</g>, vernac. form of cl. <g>γλωσσοκομεῖον</g> </f> <et> <e t=\"derivation\">(&lt; <g>γλῶσσα, κομέω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H727\">אָרוֹן</h>, <r v=\"2Sam.6.11\"></r>, <r v=\"2Chr.24.8\"></r>, <r v=\"2Chr.24.10\"></r>, <r v=\"2Chr.24.11\"></r> * ;]</e> </et> <s> <s n=\"1.\">= cl. <g>-εῖον</g> (v. supr.), <b>a case</b> for holding the reeds or tongues of musical instruments. </s> <s n=\"2.\">As in LXX, <g>π.</g> (MM, s.v.), <b>a box, chest</b>: <r v=\"John.12.6\"></r> <r v=\"John.13.29\"></r>.†</s> </s>"},"G1197":{"l":"δέσμη","o":1,"ar":"<f><o>δέσμη</o>، <g>-ης, ἡ</g> </f> <s><b>حزمة</b>: <g>δήσατε αὐτὰ εἰς δέσμας</g>، <r v=\"Matt.13.30\"></r>.†</s>","en":"<f><o>δέσμη</o> (Rec. <g>δεσμή</g>), <g>-ης, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>δέω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H92\">אֲגֻדָּה</h>, <r v=\"Exod.12.22\"></r> * ;]</e> </et> <s><b>a bundle</b>: <g>δήσατε αὐτὰ εἰς δέσμας</g> (D, Orig., omit <g>εἰς</g>, and Blass thinks original reading, <g>δέσμας δέσμας</g>; v. Deiss., <i>LAE</i>, 125<i>4</i>), <r v=\"Matt.13.30\"></r>.†</s>"},"G1193":{"l":"δερμάτινος","o":2,"ar":"<f><o>δερμάτινος</o>، <g>-η, -ον</g></f> <s><b>جلدي، من جلد</b>: <r v=\"Matt.3.4\"></r>، <r v=\"Mark.1.6\"></r> (قارن <r v=\"2Kgs.1.8\"></r>).†</s>","en":"<f><o>δερμάτινος</o>, <g>-η, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>δέρμα</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H5785\">עוֹר</h> ;] </e> </et> <s><b>of skin, leathern</b>: <r v=\"Matt.3.4\"></r>, <r v=\"Mark.1.6\"></r> (cf. <r v=\"2Kgs.1.8\"></r>).†</s>"},"G1146":{"l":"δακτύλιος","o":1,"ar":"<f><o>δακτύλιος</o>، <g>-ου, ὁ</g></f> <s><b>خاتم</b>: <r v=\"Luke.15.22\"></r>.†</s>","en":"<f><o>δακτύλιος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>δάκτυλος</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2885\">טַבַּעַת</h> ;] </e> </et> <s><b>a ring</b>: <r v=\"Luke.15.22\"></r>.†</s>"},"G1148":{"l":"Δαλμανουθά","o":1,"ar":"<f><o>Δαλμανουθά</o>، <g>ἡ</g></f> <s>لا يُصرَّف، </s> <s><b>دلمانوثة</b>، مكان غير معروف الموقع قرب بحر الجليل: <r v=\"Mark.8.10\"></r> (قارن <g>Μαγαδάν</g>).†</s>","en":"<f><o>Δαλμανουθά</o>, <g>ἡ</g></f> <s>indecl., </s> <s><b>Dalmanutha</b>, an unidentified place near the Sea of Galilee: <r v=\"Mark.8.10\"></r> (cf. <g>Μαγαδάν</g>).†</s>"},"G1191":{"l":"Δέρβη","o":3,"ar":"<f><o>Δέρβη</o>، <g>-ης, ἡ</g>، </f> <s><b>دربة</b>، مدينة في ليكأونية: <r v=\"Acts.14.6\"></r>، <r v=\"Acts.14.20\"></r> <r v=\"Acts.16.1\"></r>.†</s>","en":"<f><o>Δέρβη</o>, <g>-ης, ἡ</g>, </f> <s><b>Derbe</b>, a city of Lycaonia: <r v=\"Acts.14.6\"></r>, <r v=\"Acts.14.20\"></r> <r v=\"Acts.16.1\"></r>.†</s>"},"G1171":{"l":"δεινῶς","o":2,"ar":"<f><o>δεινῶς </o>، </f> ظرف <s n=\"1.\"><b>بشدة، بشكل مريع</b>: <r v=\"Matt.8.6\"></r>. </s> <s n=\"2.\"><b>بعنف</b>: <r v=\"Luke.11.53\"></r>.†</s>","en":"<f><o>δεινῶς </o>, </f> adv. <et> <e t=\"derivation\">(&lt; <g>δέος</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Job.10.16\"></r>, <r v=\"Wis.17.3\"></r>, al. ;]</e> </et> <s n=\"1.\"><b>terribly</b>: <r v=\"Matt.8.6\"></r>. </s> <s n=\"2.\"><b>vehemently</b>: <r v=\"Luke.11.53\"></r>.†</s>"},"G1156":{"l":"δάνιον","o":1,"ar":"<f><o>δάνιον</o>، <g>-ου, τό</g> </f> <s><b>دَين</b> (قرض): <r v=\"Matt.18.27\"></r>.†</s>","en":"<f><o>δάνιον</o>, <g>-ου, τό</g> </f> <et> <e t=\"derivation\">(late form of <g>δάνειον</g>, Rec.; v.s. <g>δανίζω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.24.11\"></r> (<h n=\"H5382\">נָשָׁה</h>) <r v=\"Deut.15.8\"></r>, <r v=\"Deut.15.10\"></r> (<h n=\"H5670\">עָבַט</h> hi.), <r v=\"4Macc.2.8\"></r> * ;]</e> </et> <s><b>a loan</b>: <r v=\"Matt.18.27\"></r>.†</s>"},"G1145":{"l":"δακρύω","o":1,"ar":"<f><o>δακρύω </o></f> <s><b>يبكي، يذرف الدموع</b>: <r v=\"John.11.35\"></r>.†</s>","en":"<f><o>δακρύω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1058\">בָּכָה</h>, etc. ;] </e> </et> <s><b>to weep, shed tears</b>: <r v=\"John.11.35\"></r>.†</s> <sy><i>SYN.</i>: <g>κλαίω</g>, of audible weeping, <b>to cry</b>; <g>ὀδύρομαι</g>, of grief expressed verbally, <b>to lament</b>; <g>θρηνέω</g>, of formal lamentation, <b>to sing a dirge</b>; <g>ἀλαλάζω</g>, <b>to wail</b> in Oriental fashion; <g>στενάζω</g>, of grief expressed by inarticulate sounds, <b>to groan</b>.</sy>"},"G1170":{"l":"δεῖνα","o":1,"ar":"<f>** <o>δεῖνα</o>، <g>ὁ, ἡ, τό</g> (حالة الجر <g>-νος</g>، حالة القابل <g>-νι</g>، حالة النصب <g>-να</g>)، </f> <s><b>فلان، شخص ما</b>، لا يستطيع المتكلم أن يسمّيه أو لا يريد: <r v=\"Matt.26.18\"></r>.†</s>","en":"<f>** <o>δεῖνα</o>, <g>ὁ, ἡ, τό</g> (gen. <g>-νος</g>, dat. <g>-νι</g>, acc. <g>-να</g>), </f> <et> <e t=\"septuagint\">[in Aq.: <r v=\"Ruth.4.1\"></r>, <r v=\"1Sam.21.2\"></r> (Sm. also), <r v=\"2Kgs.6.8\"></r> * ;]</e> </et> <s><b>such an one, a certain one</b>, whom one cannot or will not name: <r v=\"Matt.26.18\"></r>.†</s>"},"G1179":{"l":"Δεκάπολις","o":3,"ar":"<f><o>Δεκά-πολις</o>، <g>-εως, ὴ </g></f> <s><b>العشر المدن</b> (ديكابوليس)، منطقة شرقي الأردن تضم عشر مدن: <r v=\"Matt.4.25\"></r>، <r v=\"Mark.5.20\"></r> <r v=\"Mark.7.31\"></r>.†</s>","en":"<f><o>Δεκά-πολις</o>, <g>-εως, ὴ </g></f> <s><b>Decapolis</b>, a region east of the Jordan con­taining ten cities: <r v=\"Matt.4.25\"></r>, <r v=\"Mark.5.20\"></r> <r v=\"Mark.7.31\"></r>.†</s>"},"G1157":{"l":"δανιστής","o":1,"ar":"<f><o>δανιστής</o>، <g>-οῦ, ὁ</g> </f> <s><b>مُداين، مقرض</b>: <r v=\"Luke.7.41\"></r>.†</s>","en":"<f><o>δανιστής</o>, <g>-οῦ, ὁ</g> </f> <et> <e t=\"derivation\">(late form of <g>-ειστής</g>, Rec.; v.s. <g>δανείζω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Kgs.4.1\"></r>, <r v=\"LXX:Ps.108.11\"></r> (<h n=\"H5382\">נשׁה</h>), <r v=\"Prov.29.13\"></r> (<h n=\"H7326\">רָשׁ</h>), <r v=\"Sir.29.28\"></r> * ;] </e> </et> <s><b>a money-lender</b>: <r v=\"Luke.7.41\"></r>.†</s>"},"G1160":{"l":"δαπάνη","o":1,"ar":"<f><o>δαπάνη</o>، <g>-ης, ἡ </g></f> <s><b>نفقة، كلفة</b>: <r v=\"Luke.14.28\"></r>.†</s>","en":"<f><o>δαπάνη</o>, <g>-ης, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.6.4\"></r>, <r v=\"Ezra.6.8\"></r> (<h n=\"H5313\">נִפְקָא</h>), <r v=\"Bel.1.21\"></r>, al. ;] </e> </et> <s><b>expense, cost</b>: <r v=\"Luke.14.28\"></r>.†</s>"},"G1152":{"l":"Δάμαρις","o":1,"ar":"<f><o>Δάμαρις</o>، <g>-ιδος, ἡ</g></f> <s><b>دامرس</b>: <r v=\"Acts.17.34\"></r>.†</s>","en":"<f><o>Δάμαρις</o>, <g>-ιδος, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>δάμαρ</g>, poët., <b>a wife</b>), </e> </et> <s><b>Damaris</b>: <r v=\"Acts.17.34\"></r>.†</s>"},"G1102":{"l":"γναφεύς","o":1,"ar":"<f><o>γναφεύς</o>، <g>-έως, ὁ</g>، صيغة أيونية ومن <g>κοινή</g> للصيغة الأتيكية <g>κναφεύς</g> </f> <s><b>قصّار، مبيِّض الثياب</b>: <r v=\"Mark.9.3\"></r>.†</s>","en":"<f><o>γναφεύς</o>, <g>-έως, ὁ</g>, Ion. and <g>κοινή</g> form of Att. <g>κναφεύς</g> </f> <et> <e t=\"derivation\">(&lt; <g>κνάπτω</g>, <i>to card</i> wool), </e> <e t=\"septuagint\">[in LXX for <h n=\"H3526\">כָּבַס</h>, <r v=\"2Kgs.18.17\"></r>, <r v=\"Isa.7.3\"></r> <r v=\"Isa.36.2\"></r>*;]</e> </et> <s><b>a fuller, cloth-dresser</b>: <r v=\"Mark.9.3\"></r>.†</s>"},"G1155":{"l":"δανίζω","o":4,"ar":"<f><o>δανίζω</o></f> <s><b>أقرض</b> المال بالربا: <r v=\"Luke.6.34-Luke.6.35\"></r>؛ الصيغة الوسطى، <b>اقترض</b>: <r v=\"Matt.5.42\"></r>.†</s>","en":"<f><o>δανίζω</o></f> <et> <e t=\"derivation\">(late form of cl. <g>-είζω</g>, Rec., Bl., § 3; Thackeray, <i>Gr.</i>, 85 f.) </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3867\">לוה</h> (<r v=\"Prov.19.17\"></r>) ;] </e> </et> <s><b>to lend</b> money on interest: <r v=\"Luke.6.34-Luke.6.35\"></r>; mid., <b>to borrow</b>: <r v=\"Matt.5.42\"></r>.†</s> <sy><i>SYN.</i>: <g>κίχρημι</g> (v.s. <g>χράω</g>), to lend in a friendly way.</sy>"},"G1195":{"l":"δεσμεύω","o":3,"ar":"<f><o>δεσμεύω</o></f> <s n=\"1.\"><b>قيّد بالسلاسل</b>: <r v=\"Luke.8.29\"></r>، <r v=\"Acts.22.4\"></r>. </s> <s n=\"2.\"><b>ربط، حزم معًا</b>: <g>φορτία</g>، <r v=\"Matt.23.4\"></r>.†</s>","en":"<f><o>δεσμεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>δεσμός</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H631\">אָסַר</h> (<r v=\"Judg.16.11\"></r>, al.), <h n=\"H481\">אָלַם</h> pi. (<r v=\"Gen.37.7\"></r>, al.), etc. ;] </e> </et> <s n=\"1.\"><b>to put in chains</b>: <r v=\"Luke.8.29\"></r>, <r v=\"Acts.22.4\"></r>. </s> <s n=\"2.\"><b>to bind, tie together</b>: <g>φορτία</g>, <r v=\"Matt.23.4\"></r>.†</s>"},"G1168":{"l":"δειλιάω","o":1,"ar":"<f>† <o>δειλιάω</o>، <g>-ῶ</g></f> <s>= الأكثر شيوعًا <g>ἀποδ-</g>، <b>جبن، ارتعب، خاف</b>: <r v=\"John.14.27\"></r>.†</s>","en":"<f>† <o>δειλιάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>δειλία</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H2865\">חתת</h> ni., <h n=\"H6342\">פּחד</h>, etc. ;] </e> </et> <s>= the more freq. <g>ἀποδ-</g>, <b>to be cowardly, timid, fearful</b>: <r v=\"John.14.27\"></r>.†</s>"},"G1190":{"l":"Δερβαῖος","o":1,"ar":"<f><o>Δερβαῖος</o>، <g>-α, -ον </g></f> <s><b>من دربة</b>: <r v=\"Acts.20.4\"></r>.†</s>","en":"<f><o>Δερβαῖος</o>, <g>-α, -ον </g></f> <s><b>of Derbe</b>: <r v=\"Acts.20.4\"></r>.†</s>"},"G1175":{"l":"δεισιδαιμονία","o":1,"ar":"<f>*† <o>δεισιδαιμονία</o>، <g>-ας, ἡ </g></f> <s> <s n=\"1.\"><b>خوف الآلهة</b>؛ </s> <s n=\"(a)\"><b>تقوى، تديّن</b>؛ </s> <s n=\"(b)\"><b>خرافة</b>. </s> <s n=\"2.\">موضوعيًا، <b>ديانة</b>: <r v=\"Acts.25.19\"></r>.†</s> </s>","en":"<f>*† <o>δεισιδαιμονία</o>, <g>-ας, ἡ </g></f> <et> <e t=\"derivation\">(&lt; <g>δεισιδαίμων</g>, q.v.); </e> </et> <s> <s n=\"1.\"><b>fear of the gods</b>; </s> <s n=\"(a)\"><b>piety, religion</b>; </s> <s n=\"(b)\"><b>superstition</b>. </s> <s n=\"2.\">Objectively, <b>a religion</b>: <r v=\"Acts.25.19\"></r> (Cremer, 72, 682).†</s> </s>"},"G1158":{"l":"Δανιήλ","o":1,"ar":"<f><o>Δανιήλ</o>، <g>ὁ</g>، لا يُصرَّف (بالعبرية <h n=\"H1840\">דָּנִיֵּאל</h>، <b>الله قاضيّ</b>)، </f> <s><b>دانيال</b>، النبي: <r v=\"Matt.24.15\"></r>.†</s>","en":"<f><o>Δανιήλ</o>, <g>ὁ</g>, indecl. (Heb. <h n=\"H1840\">דָּנִיֵּאל</h>, <b>God is my Judge</b>), </f> <s><b>Daniel</b>, the prophet: <r v=\"Matt.24.15\"></r>.†</s>"},"G1139":{"l":"δαιμονίζομαι","o":13,"ar":"<f>** <o>δαιμονίζομαι</o></f> <s><b>كان تحت سلطان <g>δαίμων</g> </b> (انظر <g>δαιμόνιον</g>)، <b>كان به شيطان</b>: <r v=\"Matt.15.22\"></r>؛ وفي المواضع الأخرى دائمًا اسم الفاعل، <g>-ιζόμενος</g>، <g>-ισθείς</g>: <r v=\"Matt.4.24\"></r>؛ <r v=\"Matt.8.16\"></r>، <r v=\"Matt.8.28\"></r>، <r v=\"Matt.8.33\"></r>، <r v=\"Matt.9.32\"></r>، <r v=\"Matt.12.22\"></r>، <r v=\"Mark.1.32\"></r>، <r v=\"Mark.5.15\"></r>، <r v=\"Mark.5.16\"></r>، <r v=\"Mark.5.18\"></r>، <r v=\"Luke.8.36\"></r>، <r v=\"John.10.21\"></r>.†</s>","en":"<f>** <o>δαιμονίζομαι</o></f> <et> <e t=\"derivation\">(in cl. also <g>δαιμονάω</g>; &lt; <g>δαίμων</g>), </e> <e t=\"septuagint\">[in Aq.: <r v=\"LXX:Ps.90.6\"></r> * ;]</e> </et> <s><b>to be under the power of a <g>δαίμων</g> </b> (<g>δαιμόνιον</g>, q.v.), <b>to be possessed</b>: <r v=\"Matt.15.22\"></r>; elsewhere always ptcp., <g>-ιζόμενος</g>, <g>-ισθείς</g>: <r v=\"Matt.4.24\"></r>; <r v=\"Matt.8.16\"></r>, <r v=\"Matt.8.28\"></r>, <r v=\"Matt.8.33\"></r> <r v=\"Matt.9.32\"></r> <r v=\"Matt.12.22\"></r>, <r v=\"Mark.1.32\"></r> <r v=\"Mark.5.15\"></r>, <r v=\"Mark.5.16\"></r>, <r v=\"Mark.5.18\"></r>, <r v=\"Luke.8.36\"></r>, <r v=\"John.10.21\"></r> (Cremer, 171).†</s>"},"G1147":{"l":"δάκτυλος","o":8,"ar":"<f><o>δάκτυλος</o>، <g>-ου, ὁ </g></f> <s><b>إصبع</b>: <r v=\"Matt.23.4\"></r>، <r v=\"Mark.7.33\"></r>، <r v=\"Luke.11.46\"></r>، <r v=\"Luke.16.24\"></r>، <r v=\"John.8.6\"></r>، <r v=\"John.8.8\"></r>، <r v=\"John.20.25\"></r>، <r v=\"John.20.27\"></r>؛ مجازيًا، <g>δ. θεοῦ</g> (قارن <r v=\"Exod.8.19\"></r>)، <r v=\"Luke.11.20\"></r>.†</s>","en":"<f><o>δάκτυλος</o>, <g>-ου, ὁ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H676\">אֶצְבַּע</h> ;] </e> </et> <s><b>a finger</b>: <r v=\"Matt.23.4\"></r>, <r v=\"Mark.7.33\"></r>, <r v=\"Luke.11.46\"></r> <r v=\"Luke.16.24\"></r>, <r v=\"John.8.6\"></r>, <r v=\"John.8.8\"></r> <r v=\"John.20.25\"></r>, <r v=\"John.20.27\"></r>; metaph., <g>δ. θεοῦ</g> (cf. <r v=\"Exod.8.19\"></r>), <r v=\"Luke.11.20\"></r>.†</s>"},"G1187":{"l":"δεξιοβόλος","o":1,"ar":"<f>*† <o>δεξιο-βόλος</o>، <g>-ου, ὁ</g></f> <s><b>من يرمي باليد اليمنى</b>: قراءة بدلاً من <g>δεξιολάβος</g> في <r v=\"Acts.23.23\"></r>.†</s>","en":"<f>*† <o>δεξιο-βόλος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>δεξιός</g>, <g>βάλλω</g>), </e> </et> <s><b>one who throws with the right hand</b>: L for <g>δεξιολάβος</g>, <r v=\"Acts.23.23\"></r>.†</s>"}});A.got[11]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});